window.QUESTIONS = [[1,"Ban chấp hành Trung ương Đảng chủ trương thành lập nước Việt Nam dân chủ cộng hoà tại Hội nghị nào?",["Hội nghị trung ương tháng 10/1930","Hội nghị trung ương VI tháng 11/1939","Hội nghị trung ương VII tháng 11/1940","Hội nghị trung ương VIII tháng 5/1941"],"d",""],[2,"Hội nghị lần thứ 8 Ban chấp hành Trung ương Đảng Cộng sản Đông Dương (5/1941) quyết định hình thức chính quyền sau cách mạng ở Việt Nam là:",["Chính phủ cách mạng lâm thời","Chính phủ Việt Nam Dân chủ Cộng hòa","Chính phủ Xô viết công-nông-binh","Chính phủ dân chủ Cộng hòa Đông Dương"],"b",""],[3,"Chủ trương chuyển hướng chiến lược cách mạng từ làm cách mạng tư sản dân quyền sang làm cách mạng giải phóng dân tộc được đặt ra từ Hội nghị nào của Đảng?",["Hội nghị Ban Chấp hành Trung ương tháng 10/1930","Hội nghị Ban Chấp hành Trung ương tháng 11/1939","Hội nghị Cán bộ Trung ương tháng 11/1940","Hội nghị Ban Chấp hành Trung ương tháng 5/1941"],"b",""],[4,"Nội dung nào không phản ánh thành tựu của kế hoạch Nhà nước 5 năm (1961 - 1965)?",["Giá trị sản lượng công nghiệp nặng năm 1965 tăng 3 lần so với năm 1960.","Công nghiệp quốc doanh chiếm tỉ trọng 93% trong tổng giá trị sản lượng ngành công nghiệp toàn miền Bắc.","Công nghiệp nhẹ, tiểu thủ công nghiệp đã giải quyết được 80% hàng tiêu dùng thiết yếu cho nhân dân.","Thương nghiệp tư nhân được Nhà nước ưu tiên phát triển nên đã chiếm lĩnh được thị trường."],"d",""],[5,"Sự lãnh đạo toàn diện và tuyệt đối của Đảng là điểm cốt lõi của cơ sở chính trị trong hệ thống gì:",["Hệ thống chính trị Chuyên chính vô sản","Hệ thống chính trị Dân chủ nhân dân","Hệ thống chính trị thời kỳ đổi mới"],"a",""],[6,"Trong phong trào yêu nước chống Thực dân Pháp, giai cấp nào được coi là động lực của cách mạng?",["Nông dân","Công nhân","Tư sản","Tiểu tư sản"],"a",""],[7,"Trong phong trào cách mạng nước ta, giai cấp nào sẽ là lực lượng lãnh đạo cách mạng?",["Nông dân","Công nhân","Tư sản","Tiểu tư sản"],"b",""],[8,"Chiến lược \"Chiến tranh đặc biệt\" của Mĩ là",["Một hình thức mới của chủ nghĩa thực dân cũ, dựa trên nền tảng lực lượng quân ngụy, dưới sự chỉ huy của cố vấn Mĩ, bằng phương tiện chiến tranh Mĩ","Một hình thức chiến tranh của chủ nghĩa thực dân mới, được tiến hành bằng quân đội viễn chinh Mĩ và quân chư hầu","Một hình thức chiến tranh của chủ nghĩa thực dân cũ, được tiến hành bằng Quân đội lính đánh thuê, dưới sự chỉ huy của cố vấn Mĩ, phương tiện chiến tranh Mĩ","Một hình thức chiến tranh của chủ nghĩa thực dân mới, được tiến hành bằng quân đội tay sai, dưới sự chi huy của cố vấn Mĩ, bằng phương tiện chiến tranh Mĩ"],"d",""],[9,"Chiến thắng nào của ta quyết định thắng lợi tại hội nghị Giơnevơ 1954?",["Việt Bắc thu - đông 1947","Biên giới thu - dông 1950","Điện Biên Phủ 1954","Đông xuân 1953-1954"],"c",""],[10,"Hội nghị Trung ương Đảng lần thứ 11 tháng 03 năm 1965 và Hội nghị Trung ương Đảng lần thứ 12 tháng 12 năm 1965 đề ra khẩu hiệu chung của nhân dân cả nước là :",["Tất cả để đánh thắng giặc Mỹ xâm lược và tất cả cho tiền tuyến","Tất cả để thống nhất nước nhà","Tất cả vì miền Nam ruột thịt","Các phương án trả lời đều đúng"],"a",""],[11,"Đại hội lần thứ XI đề ra chiến lược phát triển kinh tế- xã hội 2011-2020 là :",["Phát triển nhanh gắn liền với phát triển bền vững","Phát tiển gắn với xây dựng","Đẩy mạnh hội nhập quốc tế","Xây dựng nền kinh tế tựu chủ"],"a",""],[12,"Nội dung nào phản ánh điểm tương đồng về nội dung giữa Hiệp định Giơ-ne-vơ năm 1954 về Đông Dương và Hiệp định Pari năm 1973 về Việt Nam?",["Hiệp định có sự tham gia của 5 cường quốc trong hội đồng bảo an Liên Hợp quốc","Các bên thừa nhận miền Nam có 2 chính quyền, 2 quân đội, 2 vùng kiểm soát và 3 lực lượng chính trị","Các nước cam kết tôn trọng những quyền dân tộc cơ bản của nhân dân Việt Nam.","Đều là văn bản mang tính pháp lí quốc tế, ghi nhận các quyền tự do cơ bản của Việt Nam."],"c",""],[13,"Về Kết quả thực hiện Nghị quyết Đại hội XII, Đại hội XIII đánh giá lĩnh vực nào dưới đây chưa trở thành động lực then chốt thúc đẩy phát triển kinh tế - xã hội?",["Giáo dục và đào tạo, khoa học và công nghệ","Khoa học và công nghệ","Văn hóa xã hội","Giáo dục và đào tạo"],"a",""],[14,"Đảng xác định vai trò của thành phần kinh tế nhà nước là :",["Giữ vai trò chủ đạo","Giữ vai trò đặc biệt","Giữ vai trò điều phối","Giữ vai trò thứ yếu"],"a","(Kiểu hỏi khác: Đảng Cộng sản Việt Nam xác định thành phần kinh tế nhà nước có vai trò như thế nào trong nên kinh tế?)"],[15,"Hoạt động chủ yếu nhất của Hội Việt Nam Cách mạng Thanh niên là:",["Xuất bản báo Thanh niên làm cơ quan tuyên truyền của Hội","Thực hiện chủ trương \"vô sản hóa\"","Mở lớp huấn luyện chính trị, đào tạo cán bộ cách mạng.","Thành lập cơ sở trong nước."],"c",""],[16,"Điều kiện nào không tạo ra khả năng đấu tranh công khai, hợp pháp cho phong trào vận động dân chủ Đông Dương (1936-1939)",["Nguy cơ chiến tranh thế giới, chủ trương của Quốc tế cộng sản và Mặt trận bình dân Pháp lên cầm quyền.","Chủ trương chuyển hướng chiến lược cách mạng của Quốc tế cộng sản và tình hình thế giới có nhiều thay đổi thuận lợi cho cách mạng","Mặt trận nhân dân Pháp lên cầm quyền và những thay đổi trong xã hội Việt Nam","Mặt trận nhân dân Pháp tan vỡ, chính quyền thực dân Pháp ở Việt Nam thi hành chính sách phát xít."],"d",""],[17,"\"Đại diện cho quyền và lợi ích hợp pháp của nhân dân\" là vai trò của tổ chức nào?",["Đảng Cộng sản Việt Nam","Đoàn thanh niên Cộng sản Hồ Chí Minh","Nhà Nước Việt Nam","Mặt trận Tổ quốc Việt Nam và các tổ chức chính trị - xã hội"],"d",""],[18,"Tại Đại hội lần thứ II Đảng cộng sản Đông Dương quyết định tách ra thành ba Đảng cách mạng ở ba nước Đông Dương. Ở Việt Nam, Đảng ra hoạt động công khai lấy tên là :",["Đảng Lao động Việt Nam","Đảng Dân chủ Việt Nam","Đảng Cách mạng Việt Nam","Đảng Xã hội Việt Nam"],"a",""],[19,"Để tránh sự chú ý và đàn áp của Pháp, Đảng ta đã tuyên bố tự giải tán vào ngày tháng năm nào và đổi tên là gì?",["2-9-1945- Đảng Cộng sản Đông Dương","25-11-1945- Hội nghiên cứu Chủ nghĩa Mác-Lênin","3-2-1946- Đảng Lao động Việt Nam","11-11-1945- Hội nghiên cứu Chủ nghĩa Mác ở Đông Dương"],"d",""],[20,"Từ năm 1954 đến năm 1975, Mỹ đã thực hiện mấy loại hình chiến tranh ở Việt Nam?",["2 loại hình chiến tranh","3 loại hình chiến tranh","4 loại hình chiến tranh","5 loại hình chiến tranh"],"c","Mỹ đã triển khai ở Việt Nam 4 chiến lược chiến tranh, đó là \"Chiến tranh một phía\", \"Chiến tranh đặc biệt\", \"Chiến tranh cục bộ\" và \"Việt Nam hóa chiến tranh\", do 5 đời tổng thống kế tiếp nhau quyết tâm thực hiện."],[21,"Việt Nam chính thức trở thành thành viên của tổ chức WTO vào thời gian nào?",["11/1/2006","11/1/2007","11/1/2008","11/1/2009"],"b",""],[22,"Mặt trận Tổ quốc Việt Nam, Đoàn thanh niên Lao động HCM, Tổng Công đoàn Việt Nam, Hội Liên hiệp phụ nữ Việt Nam v.v. được gọi là :",["Đảng cộng sản Việt Nam.","Các tổ chức đoàn thể","Mặt trận tổ quốc Việt Nam","Các tổ chức chính trị - xã hội"],"d",""],[23,"Nhiệm vụ chống giặc dốt sau Cách mạng tháng Tám (1945) thể hiện qua phong trào nào sau đây?",["Toàn dân đưa trẻ đến trường","Toàn dân tham gia xóa nạn mù chữ","Bình dân học vụ","Truyền bá quốc ngữ"],"c",""],[24,"Điền thêm từ còn thiếu trong câu trích từ Nghị quyết Hội nghị ban chấp hành Trung ương Đảng lần 24 (1975) : \".... đất nước vừa là nguyện vọng tha thiết của nhân dân cả nước, vừa là quy luật khách quan cửa sự phát triển cách mạng Việt Nam, của lịch sử dân tộc Việt Nam\"",["Độc lập","Thống nhất","Giải phóng","Độc lập và Thống nhất"],"b",""],[25,"Pháp thực hiện rút quân khỏi miền Nam Việt Nam trong bối cảnh nào ?",["Tất cả mọi điều khoản được quy định tại Hiệp định đã được hoàn tất.","Pháp đã hoàn tất chuyển giao mọi trách nhiệm thi hành Hiệp định Giơ-ne-vơ cho chính quyền Bửu Lộc.","Pháp đã xúc tiến mọi việc cho công cuộc thống nhất đất nước bằng con đường tổng tuyển cử hai miền.","Rất nhiều điều khoản trong Hiệp định Giơ-ne-vơ chưa được hoàn tất."],"d",""],[26,"Một trong những đột phá chến lược mà Đại hội XIII đề ra là:",["Xây dựng hệ thống kết cấu hạ tầng đồng bộ, hiện đại cả về kinh tế- xã hội","Đổi mới chính trị, đồng thời, từng bước đổi mới hệ thống chính trị","Đổi mới tư duy an ninh quốc phòng, đồng thời, từng bước đổi mới hệ thống chính trị","Đổi mới an sinh xã hội, đồng thời, từng bước đổi mới hệ"],"a",""],[27,"Tại sao phải Tăng cường công tác kiểm tra, giám sát của Đảng?",["Đảng là nhân tố hàng đầu lãnh đạo cách mạng Việt Nam thắng lợi.","Kiểm tra, giám sát là nội dung rất quan trọng trong lãnh đạo của Đảng.","Kiểm tra, giám sát là nội dung rất quan trọng trong lãnh đạo của Đảng, điều kiện để xây dựng Đảng trong sạch vững mạnh.","Kiểm tra, giám sát là nội dung rất quan trọng trong lãnh đạo của Đảng, là nhiệm vụ thường xuyên của toàn Đảng, trước hết là cấp ủy và người đứng đầu cấp ủy."],"d",""],[28,"Trong cuộc khai thác thuộc địa lần thứ nhất của thực dân Pháp (1897 - 1913) ở Việt Nam đã xuất hiện những giai cấp, tầng lớp mới nào?",["Địa chủ và nông dân","Tư sản, tiểu tư sản và công nhân","Địa chủ, nông dân và công nhân","Nông dân và tiểu tư sản"],"b",""],[29,"Ngày 17/2/1979, quân đội nước nào tấn công biên giới phía Bắc nước ta?",["Mỹ","Khơme đỏ","Trung Quốc","Pháp"],"c",""],[30,"Hình thức đấu tranh chủ yếu trong phong trào 1930-1931 của nhân dân Nghệ - Tĩnh là gì?",["Bãi công chính trị.","Biểu tình có vũ trang tự vệ.","Mít tinh đòi quyền dân chủ.","Đưa yêu sách cải thiện đời sống."],"b",""],[31,"Tên gọi \"Nước Cộng hoà xã hội chủ nghĩa Việt Nam\" có từ khi nào ?",["Ngày 2/9/1945.","Ngày 2/7/1976.","Ngày 12/2/1951.","Ngày 2/7/1975."],"b",""],[32,"Nguyên nhân căn bản nhất dẫn đến sự thắng lợi của cuộc kháng chiến chống Pháp là",["Có sự lãnh đạo của Đảng với đường lối kháng chiến đúng.","Có lực lượng vũ trang gồm 3 thứ quân dũng cảm, mưu lược.","Có chính quyền dân chủ nhân dân tổ chức toàn dân kháng chiến và xây dựng chế độ mới.","Có liên minh đoàn kết chiến đấu Việt Nam, Lào, Campuchia; sự ủng hộ của các nước XHCN và thế giới."],"a",""],[33,"Sự kiện nào đánh dấu Việt Nam thống nhất về mặt Nhà nước sau năm 1975?",["Chiến dịch Hồ Chí Minh toàn thắng (4/1975)","Hội nghị Hiệp thương chính trị của hai đoàn đại biểu Nam - Bắc (11/1975)","Tổng tuyển cử bầu Quốc hội khóa VI (4/1976)","Đại hội Đảng toàn quốc lần thứ IV (12/1976)"],"c",""],[34,"Cương lĩnh đầu tiên của Đảng đã xác định mục tiêu chiến lược của cách mạng Việt Nam là gì?",["Xây dựng một nước Việt Nam dân giàu, nước mạnh, dân chủ, công bằng, văn minh","Xây dựng một nước Việt Nam dân giàu mạnh","Làm tư sản dân quyền cách mạng và thổ địa cách mạng để đi tới xã hội cộng sản","Cách mạng tư sản dân quyền, lập chính quyền của công nông bằng hình thức Xô viết, để dự bị điều kiện đi tới cách mạng xã hội chủ nghĩa"],"c",""],[35,"Hội nghị nào của Đảng mở đường cho phong trào \"Đồng khởi\" ở miền Nam năm 1960?",["Hội nghị Trung ương 12 khóa II của Đảng (3/1957)","Hội nghị Trung ương 1 khóa II của Đảng (12/1957)","Hội nghị Trung ương 14 khóa II của Đảng (11/1958)","Hội nghị Trung ương 15 khóa II của Đảng (1/1959)"],"d","(Kiểu hỏi tương tự: Hội nghị Trung ương nào của Đảng đê ra nghị quyết mở đường cho sự bùng nổ của phong trào Đồng Khởi ở miền Nam đầu năm 1960?)"],[36,"Kết quả lớn nhất mà quân và dân ta đạt được trong chiến dịch Việt Bắc - Thu Đông 1947 là",["Đánh bại âm mưu, kế hoạch đánh nhanh thắng nhanh của thực dân Pháp","Tiêu diệt bộ phận lớn sinh lực địch","Bộ đội chủ lực ta trưởng thành, lớn mạnh","Đẩy quân Pháp vào thế bị động trên chiến trường"],"a",""],[37,"Đại hội đại biểu toàn quốc lần thứ hai của Đảng họp tại đâu?",["Cao Bằng","Bắc Kạn","Tuyên Quang","Thái Nguyên"],"c",""],[38,"Sau năm 1975, đất nước ta bước vào thời kì",["kinh tế thị trường xã hội chủ nghĩa.","đất nước ta đã hòa bình, độc lập thống nhất, cả nước quá độ lên chủ nghĩa xã hội.","xây dựng xã hội chủ nghĩa.","công nghiệp hóa, hiện đại hóa."],"b",""],[39,"Hội nghị lần thứ 8 Ban chấp hành Trung ương Đảng Cộng sản Đông Dương (5/1941) đã nhấn mạnh nhiệm vụ trọng tâm của toàn Đảng, toàn dân là :",["Xây dựng lực lượng chính trị","Xây dựng lực lượng vũ trang","Chuẩn bị khởi nghĩa","Khởi nghĩa từng phần"],"c",""],[40,"Hai khẩu hiệu mà Đảng ta vận dụng trong phong trào cách mạng 1930- 1931 là:",["\"Độc lập dân tộc\" và \"Ruộng đất dân cày\".","\"Tự do dân chủ\" và \"cơm áo hòa bình\".","\"Giải phóng dân tộc\" và \"tịch thu ruộng đất của đế quốc Việt gian\".","\"Chống đế quốc\" và \"Chống phát xít, chống chiến tranh\"."],"a",""],[41,"Tình hình nước ta được ví như \"ngàn cân treo sợi tóc\" vào thời gian nào?",["Ngay sau cách mạng Tháng Tám 1945 thành công","Trước cách mạng Tháng 8","Ngay sau cuộc kháng chiến chống Mỹ thắng lợi 1975","Ngay sau khi Hiệp định Pari được ký kết 1973"],"a",""],[42,"Trong đường lối Chiến lược phát triển kinh tế - xã hội 2011-2020 Đảng ta chú trọng phát triển vấn đề nào sau đây?",["Phát triển công nghiệp hóa xã hội chủ nghĩa, xây dựng cơ sở vật chất - kỹ thuật của chủ nghĩa xã hội","Phát triển công nghiệp hóa hiện đại hóa nông nghiệp nông thôn...","Đẩy mạnh công nghiệp hóa xã hội chủ nghĩa, xây dựng cơ sở vật chất - kỹ thuật của chủ nghĩa xã hội, đưa nền kinh tế nước ta từ sản xuất lớn lên sản xuất đại quy mô xã hội chủ nghĩa.","Phát triển nhanh nguồn nhân lực, nhất là nguồn nhân lực chất lượng cao."],"d",""],[43,"Đổi mới không phải là thay đổi mục tiêu chủ nghĩa xã hội mà phải",["làm cho chủ nghĩa xã hội ngày càng tốt đẹp hơn.","làm cho mục tiêu ấy được thực hiện có hiệu quả.","làm cho mục tiêu đã đề ra nhanh chóng được thực hiện.","làm cho mục tiêu đã đề ra phù hợp với thực tiễn đất nước."],"b",""],[44,"Chánh cương vắn tắt, Sách lược vắn tắt do Hội nghị thành lập Đảng thông qua đã đặt nhiệm vụ gì lên hàng đầu?",["Nhiệm vụ chống tư sản","Nhiệm vụ chống phong kiến","Nhiệm vụ chống tay sai phản động","Nhiệm vụ chống đế quốc"],"d",""],[45,"Tại Đại hội lần thứ V của Đảng đã bầu chức vụ Tổng Bí Thư Đảng là:",["Lê Duẩn","Trường Chinh","Phạm Hùng","Nguyễn Hữu Thọ"],"a","(Kiểu hỏi khác: Đại hội Đảng lần thứ IV (12/1976) đã bầu ai làm Tổng Bí thư? A. Tôn Đức Thắng B. Trường Chinh C. Phạm Văn Đồng D. Lê Duẩn)"],[46,"Nguyên nhân chủ yếu và có ý nghĩa quyết định sự bùng nổ và phát triển của cao trào cách mạng Việt Nam năm 1930?",["Tác động tiêu cực của cuộc khủng hoảng kinh tế 1929-1933","Chính sách khủng bố trắng của đế quốc Pháp","Chính sách tăng cường vơ vét bóc lột của đế quốc Pháp","Sự lãnh đạo của Đảng Cộng sản Việt Nam"],"d",""],[47,"Một trong những quan điểm của Đảng ta về Công nghiệp hóa- hiện đại hóa đất nước là:",["Tập hợp, vận động, đoàn kết rộng rãi các tầng lớp nhân dân","Đại diện cho quyền và lợi ích hợp pháp của nhân dân","Đề xuất các chủ trương, chính sách về kinh tế, văn hóa, an ninh, quốc phòng","Lấy việc phát huy nguồn lực con người là yếu tố cơ bản cho sự phát triển nhanh và bền vữn"],"d",""],[48,"Một trong những sự kiện làm bùng nổ phong trào Đồng khởi năm 1960 là :",["Ngăn cản hiệp thương, tổng tuyển cử thống nhất đất nước","Ban hành Luật 10/59","Lập ấp chiến lược","Các phương án trả lời đều đúng"],"b",""],[49,"Tổng Bí thư của Đảng được bầu tại Hội nghị Trung ương tháng 10/1930 là",["Trần Phú","Lê Hồng Phong","Hà Huy Tập","Nguyễn Văn Cừ"],"a","(Kiểu hỏi khác: Người soạn thảo Luận cương chính trị của Đảng Cộng sản Đông Dương (10/1930) là A. Nguyễn Ái Quốc B. Lê Hồng Phong C. Hà Huy Tập D. Trần Phú)"],[50,"Đảng ta đã phát động phong trào gì để ủng hộ nhân lực cho Nam Bộ kháng chiến chống Pháp từ ngày 23-9-1945?",["Vì miền Nam \"thành đồng Tổ quốc\"","Hướng về miền Nam ruột thịt","Nam tiến","Tất cả trên đúng."],"c",""],[51,"Hiệp định Pari về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam được ký kết (1973) đã cam kết:",["Tôn trọng độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ của nước Việt Nam","Tôn trọng độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ của nước Việt Nam Dân chủ Cộng hòa","Tôn trọng độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ của nước Việt Nam Cộng hòa","Tôn trọng độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ của Cộng hòa Miền Nam Việt Nam"],"a",""],[52,"Phong trào Đồng khởi làm thất bại loại hình chiến lược chiến tranh nào của Mỹ?",["Chiến tranh đơn phương","Chiến tranh đặc biệt","Chiến tranh cục bộ","Việt Nam hóa chiến tranh"],"a",""],[53,"Nội dung chủ yếu của đấu tranh giai cấp trong thời kỳ Đổi mới được Đảng Cộng sản Việt Nam xác định là",["Lật đổ giai cấp địa chủ phong kiến","Xóa bỏ giai cấp tư sản","Thực hiện thắng lợi sự nghiệp công nghiệp hóa, hiện đại hóa theo định hướng xã hội chủ nghĩa","Không còn đấu tranh giai cấp"],"c",""],[54,"Âm mưu của Mỹ trong chiến lược chiến tranh đặc biệt là :",["Dùng người Việt đánh người Việt","Dùng người Mỹ đánh người Việt","Dùng người Đông Dương đánh người đông Dương","Dùng người Việt đánh người Việt và dùng người Đông Dương đánh người đông Dương"],"a",""],[55,"Động lực của công nghiệp hóa, hiện đại hóa trong thời kỳ Đổi mới được đưa ra tại Đại hội VIII của Đảng (1996) là:",["Giáo dục và đào tạo","Khoa học và công nghệ","Quốc phòng an ninh","Văn hóa xã hội"],"b",""],[56,"Nội dung nào không có trong \"Luận cương chính trị\" tháng 10 năm 1930?",["Đặt nhiệm vụ chống đế quốc, giải phóng dân tộc lên hàng đầu.","Đánh giá không đúng vai trò cách mạng của tầng lớp tiểu tư sản, phủ nhận mặt tích cực của tư sản dân tộc.","Không nêu được mâu thuẫn chủ yếu là mâu thuẫn giữa dân tộc Việt Nam và đế quốc Pháp.","Không đề ra được chiến lược liên minh dân tộc và giai cấp rộng rãi"],"a",""],[57,"Tháng 11/2006, Bộ Chính trị khóa 10 ra Chỉ thị số 3-NQ/TW là quyết định tổ chức cuộc vận động :",["Nói đi đôi với làm","Phát triển kinh tế tăng trưởng ổn định, hiệu quả.","Thi đua lập thành tích chào mừng Đại hội","Học tập và làm theo tấm gương đạo đức Hồ Chí Minh."],"d",""],[58,"Luận cương chính trị của Đảng Cộng sản Đông Dương tháng 10/1930 xác định:",["Mâu thuẫn giai cấp diễn ra gay gắt ở Việt Nam","Mẫu thuẫn dân tộc là chủ yếu","Nhiệm vụ giải phóng dân tộc được đặt lên hàng đầu","Liên minh dân tộc và giai cấp được thiết lập rộng rãi"],"a",""],[59,"Chính cương vắn tắt, Sách lược vắn tắt ... do Nguyễn Ái Quốc soạn thảo được thông qua tại Hội nghị thành lập Đảng được xem là :",["Văn kiện của Đảng","Tài liệu chính trị đặc biệt của Đảng","Nghị quyết của Đảng Cộng sản Việt Nam","Cương lĩnh chính trị đầu tiên của Đảng Cộng sản Việt Nam"],"d",""],[60,"Phương châm tác chiến của Quân đội nhân dân Việt Nam trong chiến dịch Điện Biên Phủ là",["Đánh nhanh, thẳng nhanh","Đánh thần tốc, táo bạo, chắc thắng","Đánh thần tốc, táo bạo, bất ngờ","Đánh chắc, tiến chắc"],"d",""],[61,"Đại hội II Đảng Lao động Việt Nam vạch ra hai đối tượng của cách mạng Việt Nam là:",["Chủ nghĩa đế quốc xâm lược và phong kiến","Bọn can thiệp Mỹ và phong kiến phản động","Đế quốc Pháp và phong kiến phản động","Đế quốc Pháp và bọn can thiệp Mỹ"],"a",""],[62,"Hiệp định Pari về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam được ký kết (1/1973) đánh dấu hoàn thành nhiệm vụ của cách mạng miền Nam, đó là",["Thống nhất đất nước","Giải phóng miền Nam","Buộc quân đội Mỹ rút khỏi miền Nam","Chiến tranh kết thúc"],"c",""],[63,"Đại hội đại biểu toàn quốc lần thứ III của Đảng được tổ chức tại :",["Sài Gòn","Hà Nội","Tân Trào","Hóc môn"],"b",""],[64,"Nhiệm vụ nào được đặt ra một cách bức thiết sau năm 1975?",["Điều chỉnh các chủ thể kinh tế, các hành vi sản xuất kinh doanh và các quan hệ kinh tế.","Phát triển các đạo luật, các quy chế, chuẩn mực về kinh tế.","Thống nhất đất nước về mặt nhà nước.","Khôi phục kinh tế sau chiến tranh."],"c",""],[65,"Trước cuộc khai thác thuộc địa lần thứ nhất của thực dân Pháp (1897 - 1913) ở Việt Nam có những giai cấp nào?",["Địa chủ và nông dân","Địa chủ, nông dân, tư sản, tiểu tư sản và công nhân","Địa chủ, nông dân và công nhân","Nông dân và tiểu tư sản"],"a",""],[66,"Tổng bí thư đầu tiên của nước ta là :",["Trần Phú","Nguyễn Văn Cừ","Trường Chinh","Lê Hồng Phong"],"a",""],[67,"Pháp chấp nhận đàm phán với Việt Nam ở Hội nghị Giơnevơ năm 1954 về Đông Dương vì:",["Sức ép của Liên Xô","Bị thất bại ở Điện Biên Phủ","Dư luận nhân dân thế giới phản đối","Pháp sợ Trung Quốc đưa quân sang giúp đỡ Việt Nam"],"b",""],[68,"Sau khi Mỹ thực hiện chiến lược \"chiến tranh cục bộ\", Đảng xác định nhiệm vụ cách mạng của miền Bắc là:",["Chuyển hướng xây dựng kinh tế, bảo đảm tiếp tục xây dựng miền Bắc vững mạnh trong điều kiện có chiến tranh","Tiếp tục xây dựng kinh tế ở miền Bắc làm cho miền Bắc trở thành hậu phương lớn của cả nước","Không tiếp tục xây dựng kinh tế ở miền Bắc để tập trung cho phát triển lực lượng quốc phòng.","Không chuyển hướng xây dựng kinh tế, tiếp tục phát triển kế hoạch 5 năm ở miền Bắc."],"a",""],[69,"Kỳ họp thứ nhất Quốc hội khóa VI (24/6 - 3/7/1976) quyết định đặt tên nước ta là:",["Cộng hòa xã hội chủ nghĩa Việt Nam","Cộng hòa Việt Nam","Cộng hòa Dân chủ Việt Nam","Việt Nam Dân chủ Cộng hòa"],"a",""],[70,"Đường lối đối ngoại \"Việt Nam sẵn sàng là bạn, là đối tác tin cậy của các nước trong cộng đồng quốc tế, phần đấu vì hòa bình, độc lập và phát triển\" được đưa ra ở Đại hội nào của Đảng?",["Đại hội VII (1991)","Đại hội VIII (1996)","Đại hội IX (2001)","Đại hội X (2006)"],"c","(Kiểu hỏi khác: Đường lối đối ngoại \"Việt Nam muốn là bạn với tất cả các nước trong cộng đồng thế giới, phấn đấu vì hòa bình,độc lập và phát triển\" được Đảng đề ra tại Đại hội lần thứ mấy? Chủ trương trong quan hệ quốc tế của Việt Nam được Đại hội Đảng lần thứ IX đưa ra là: A. Việt Nam sẵn sàng là bạn, là đối tác tin cậy của các nước trong động đồng quốc tế, phấn đấu vì hòa bình độc lập và phát triển. B. Việt Nam muốn là bạn, là đối tác tin cậy của các nước trong động đồng quốc tế, phấn đấu vì hòa bình độc lập và phát triển. C. Việt Nam là bạn, là đối tác tin cậy của các nước trong động đồng quốc tế, phấn đấu vì hòa bình độc lập và phát triển. D. Việt Nam mong là bạn, là đối tác tin cậy của các nước trong động đồng quốc tế, phấn đấu vì hòa bình độc lập và phát triển.)"],[71,"Đảng Cộng sản Đông Dương quyết định chuyển hướng đấu tranh, đặt nhiệm vụ giải phóng dân tộc lên hàng đầu trong thời kì 1939-1945 là do:",["Chiến tranh thế giới thứ hai bùng nổ","Pháp ra sức vơ vét, bóc lột nhân dân","Phát xít Nhật vào miền Bắc Việt Nam","Mâu thuẫn với Pháp-Nhật trở nên gay gắt"],"d",""],[72,"Chiến tranh thế giới thứ II nổ ra vào thời gian nào?",["1937","1938","1939","1940"],"c","(01-9)"],[73,"Đại hội nào sau đây được đánh dấu là \"Đại hội kháng chiến thắng lợi\" ?",["Hội nghị thành lập Đảng 1930","Đại hội Quốc dân ở Tân Trào 1945","Đại hội lần thứ II của Đảng 1951","Đại hội Đại biểu lần thứ III của Đảng 1960"],"c",""],[74,"Một trong những bài học về đổi mới đất nước (1986-1996 ) là:",["Kết hợp chặt chẽ đổi mới kinh tế với đổi mới chính trị, lấy đổi mới kinh tế làm trọng tâm, từng bước đổi mới chính trị.","Đổi mới tư duy và phương thức hoạt động của các bộ phận cấu thành hệ thống.","Đổi mới nhận thức và phương thức hoạt động của các bộ phận cấu thành hệ thống.","Đổi mới tư tưởng và phương thức hoạt động của các bộ phận cấu thành hệ thống."],"a",""],[75,"Điều kiện trực tiếp mở ra Phong trào dân chủ 1936 - 1939 do Đảng lãnh đạo là",["Khủng hoảng kinh tế thế giới 1929 - 1933","Quốc tế Cộng sản thay đổi chủ trương","Đảng Cộng sản Đông Dương ban hành chính sách mới","Chính phủ Mặt trận nhân dân lên cầm quyền ở Pháp"],"d",""],[76,"Hội nghị thành lập Đảng Cộng sản Việt Nam thông qua mấy văn kiện do lãnh tụ Nguyễn Ái Quốc soạn thảo?",["2 văn kiện","3 văn kiện","4 văn kiện","5 văn kiện"],"d","(Các văn kiện gồm Chánh cương vắn tắt, Sách lược vắn tắt, Chương trình tóm tắt, Điều lệ vắn tắt và Lời kêu gọi)"],[77,"Hội nghị Trung ương VIII khóa IX đã ban hành Nghị quyết số 36 - NQ/TW ngày 26/3/2004 về công tác đối với",["Biến đổi khí hậu","Công nghiệp hóa, hiện đại hóa","Người Việt Nam ở nước ngoài","Phát triển giáo dục"],"c",""],[78,"Điền vào chỗ trống: Đêm 9/3/1945, Nhật đảo chính Pháp, ngày 12-3-1945, ... đã ra Bản Chỉ thị \"Nhật Pháp bắn nhau và hành động của chúng ta\"",["Ban Thường vụ Trung ương Đảng","Trung ương cục miền Nam","Quốc dân đại hội","Đại hội toàn quốc của Đảng"],"a",""],[79,"Hội nghị của Ban chấp hành Trung ương nào sau đây nhấn mạnh giải phóng dân tộc là nhiệm vụ bức thiết nhất?",["Hội nghị trung ương I tháng 10/1930","Hội nghị trung ương VI tháng 11/1939","Hội nghị trung ương VII tháng 11/1940","Hội nghị trung ương VIII tháng 5/1941"],"d","(Kiểu hỏi khác: Hội nghị trung ương VIII tháng 5/1941 nhấn mạnh điều gì -> Giải phóng dân tộc là nhiệm vụ bức thiết nhất)"],[80,"Hình thức khởi nghĩa chống lại ách thống trị của Mĩ - Diệm đã diễn ra đầu tiên ở đâu ?",["Bến Tre.","Bình Định, Ninh Thuận.","Quảng Ngãi.","Tây Ninh."],"b",""],[81,"Ý nghĩa quan trọng của phong trào Đồng khởi là :",["Chuyển cách mạng miền Nam từ thế giữ gìn lực lượng sang thế tiến công","Lật đổ chính quyền Mỹ- Diệm","Mỹ phải ngồi vào bàn đàm phán","Mỹ phải kí hiệp định Pari"],"a",""],[82,"Kẻ thù chủ yếu của xã hội Việt Nam trong thời kì 1930-1931 là :",["Thực dân Pháp","Địa chủ phong kiến","Đế quốc và phong kiến","Địa chủ phong kiến, tư sản"],"c",""],[83,"Việt Nam hoàn thành nhiệm vụ thống nhất đất nước về mặt nhà nước vào",["tháng 5/1975.","tháng 9/1975","tháng 7/1976.","tháng 12/1976."],"c",""],[84,"Nhân dân Việt Nam thực hiện nhiệm vụ chống chế độ phản động thuộc địa, chống phát xít, chống chiến tranh trong phong trào nào sau đây?",["Phong trào cách mạng 1930 - 1931","Phong trào dân chủ 1936 - 1939","Phong trào dân tộc dân chủ 1919 - 1925","Phong trào dân tộc dân chủ 1925 - 1930"],"b",""],[85,"Chính sách đối ngoại \"làm cho nước mình ít kẻ thù hơn hết, nhiều bạn đồng minh hơn hết\" được nêu ra trong văn kiện nào của Đảng?",["Tuyên ngôn độc lập (2/9/1945)","Chỉ thị Kháng chiến kiến quốc (25/11/1945)","Hiến pháp năm 1946 (9/11/1946)","Lời kêu gọi toàn quốc kháng chiến (19/12/1946)"],"b",""],[86,"Một trong những mục tiêu của kế hoạch phát triển kinh tế và văn hóa 5 năm lần thứ 2 từ 1976 - 1980 của cả nước là:",["Đổi mới tổ chức và phương thức hoạt động của Đảng","Đổi mới tổ chức và phương thức hoạt động của Nhà nước","Đổi mới tổ chức và phương thức hoạt động kinh tế xã hội chủ nghĩa","Bảo đảm nhu cầu đời sống của nhân dân, tích lũy để xây dựng cơ sở vật chất kỹ thuật của chủ nghĩa xã hội"],"d",""],[87,"Cuộc kháng chiến chống Mỹ, cứu nước của nhân dân Việt Nam (1954-1975) kết thúc bằng thắng lợi của chiến dịch nào?",["Hồ Chí Minh","Tây Nguyên","Huế - Đà Nẵng.","Đường 14 - Phước Long."],"a",""],[88,"Giai cấp công nhân Việt Nam ra đời từ :",["Cuộc khai thác thuộc địa lần thứ nhất của thực dân Pháp","Cuôc khai thác thuộc địa lần thứ hai của thực dân Pháp","Cuộc xâm lược lần thứ nhất của thực dân Pháp","Cuộc xâm lược lần thứ hai của thực dân Pháp"],"a",""],[89,"Đại hội Đảng lần thứ VIII họp tại Hà Nội từ ngày 28/6 - 1/7/1996 diễn ra trong bối cảnh nào?",["Cách mạng khoa học và công nghệ phát triển với trình độ cao, chủ nghĩa xã hội hiện thực lâm vào thoái trào.","Thời kỳ quá độ lên chủ nghĩa xã hội đạt nhiều thành tựu to lớn,","Cách mạng khoa học và công nghệ phát triển với trình độ cao","Phong trào giải phóng dân tộc phát triển mạnh"],"a",""],[90,"Việt Nam gia nhập tổ chức ASEAN năm nào?",["1993","1994","1995","1997"],"c","(Kiểu hỏi khác: Việt Nam trờ thành thành viên chính thức của Hiệp hội các quốc gia Đông Nam Á (ASEAN) vào năm:)"],[91,"Sau đại thắng mùa xuân 1975, đất nước độc lập thống nhất, Chủ tịch nước là:",["Phạm Hùng","Tôn Đức Thắng","Phạm Văn Đồng","Nguyễn Văn Linh"],"b",""],[92,"Trưởng đoàn đại diện cho phái đoàn Chính phủ Việt Nam Dân chủ Cộng hòa tại Hội nghị Giơnevơ là ai?",["Hồ Chí Minh","Trường Chinh","Phạm Văn Đồng","Võ Nguyên Giáp"],"c",""],[93,"Đường lối chung xây dựng XHCN ở miền Bắc (1954-1975) được đề cập ở Đại hội lần thứ mấy của Đảng?",["Đại hội II","Đại hội III","Đại hội IV","Đại hội V"],"b",""],[94,"Điểm khác nhau giữa Luận cương chính trị tháng 10/1930 với Cương lĩnh chính trị đầu tiên (2/1930) của Đảng là",["Đường lối quốc tế của cách mạng giải phóng dân tộc","Đường lối tập hợp lực lượng bên trong của cách mạng","Phương pháp tiến hành cách mạng","Không có điểm khác nhau giữa 2 văn kiện"],"b",""],[95,"Đại hội III (9-1960) của Đảng đã thông qua đường lối nào?",["Đánh đuổi thực dân Pháp và can thiệp Mỹ xâm lược, giành độc lập và thống nhất thật sự cho dân tộc","Cả nước quá độ đi lên chủ nghĩa xã hội","Phát triển chế độ dân chủ nhân dân, gây cơ sở cho chủ nghĩa xã hội","Đường lối cách mạng xã hội chủ nghĩa ở miền Bắc và cách mạng dân tộc dân chủ nhân dân ở miền Nam"],"d",""],[96,"Đại biểu của tổ chức cộng sản nào không tham dự Hội nghị thành lập Đảng đầu năm 1930?",["Đông Dương cộng sản liên đoàn","An Nam cộng sản Đảng","Đông Dương cộng sản Đảng","Quốc tế cộng sản"],"a",""],[97,"Một trong những nội dung của Đại hội lần thứ IV của Đảng (12-1976) là:",["Kế hoạch nhà nước 5 năm 1976 - 1980","Phương hướng đổi mới đất nước","Tổng kết 10 năm đổi mới đất nước","Hàn gắn vết tHương chiến tranh"],"a",""],[98,"Trong mười năm từ 1979 - 1989, quan hệ Việt Nam- Trung Quốc trong tình hình :",["Thân thiện","Phức tạp","Đóng băng","Bình thường hóa"],"b",""],[99,"Đại hội lần thứ III của Đảng họp tại thủ đô Hà Nội từ ngày 5 đến ngày 10/09/1960. Đại hội đã hoàn chỉnh đường lối chiến lược chung của cách mạng Việt Nam trong giai đoạn mới và vạch ra hai nhiệm vị chiến lược đó là:",["Tiến hành cách mạng xã hội chủ nghĩa ở miền Bắc. Giải phóng miền Nam khỏi ách thống trị của đế quốc Mỹ và bọn tay sai, thực hiện thống nhất nước nhà, hoàn thành độc lập và dân chủ trong cả nước","Tiến hành cách mạng dân chủ nhân dân ở miền Bắc. Giải phóng miền Nam khỏi ách thống trị của đế quốc Mỹ và bọn tay sai, thực hiện thống nhất nước nhà, hoàn thành độc lập và dân chủ trong cả nước. Tiến hành cách mạng dân tộc dân chủ ở miền Bắc","Giải phóng miền Nam khỏi ách thống trị của đế quốc Mỹ và bọn tay sai, thực hiện thống nhất nước nhà, hoàn thành độc lập và dân chủ trong cả nước"],"a","(Kiểu hỏi khác: Đại hội Đảng lần thứ III (9/1960) xác định mục tiêu chung trước mắt của cả nước là: A. Hoàn thành cách mạng xã hội chủ nghĩa B. Lật đồ chế độ độc tài gia đình trị ở miền Nam C. Đánh đuổi quân đội Mỹ khỏi miền Nam D. Giải phóng miền Nam, hòa bình, thống nhất Tổ quốc Kiểu hỏi khác: Nhiệm vụ chiến lược của cách mạng được Đại hội Đảng toàn quốc lần thứ III để ra là gì?)"],[100,"Đại hội Đảng lần thứ II xác định con đường đi lên chủ nghĩa xã hội là một quá trình :",["Đấu tranh lâu dài, đại thể trải qua ba giai đoạn","Đấu tranh kiên trì, đại thể trải qua bốn giai đoạn","Đấu tranh lâu dài, đại thể trải qua năm giai đoạn","Đấu tranh kiên trì, đại thể trải qua hai giai đoạn"],"a",""],[101,"Đâu là hạn chế của Đảng trong quá trình lãnh đạo, chỉ đạo các hoạt động quân sự năm 1968?",["Thiếu tính sáng tạo, bất ngờ, táo bạo","Có biểu hiện chủ quan trọng việc đánh giá tình hình, đề ra yêu cầu chưa sát với thực tế","Các trận đánh không có ý nghĩa chiến lược","Không buộc địch phải xuống thang chiến tranh"],"b",""],[102,"Sự kiện nào được Nguyễn Ái Quốc đánh giá \"là một bước ngoặt vô cùng quan trọng trong lịch sử Cách mạng Việt Nam ta\"?",["Đảng Cộng sản Việt Nam ra đời","Sự thành lập Đảng Cộng sản Pháp","Sự thành lập hội Việt Nam Cách mạng thanh niên","Nguyễn Ái Quốc tìm thấy con đường cứu nước"],"a",""],[103,"Đại hội lần thứ mấy của Đảng đã lần đầu tiên khẳng định một bài học trong quá trình đổi mới đất nước là phải \"lấy lợi ích quốc gia, dân tộc lẫm mục tiêu cao nhất\"?",["Đại hội X (2006)","Đại hội XI (2011)","Đại hội XII (2016)","Đại hội XIII (2021)"],"c",""],[104,"Một trong những nội dung phát triển kinh tế mà Đại hôi Đảng lần thứ VI đề ra là :",["Mở rộng và nâng cao hiệu quả kinh tế thị trường","Phát triển kinh tế tư nhân","Mở rộng và nâng cao hiệu quả kinh tế đối ngoại.","Mở rộng phất triển kinh tế hợp tác xã"],"c",""],[105,"Đại hội đại biểu toàn quốc của Đảng cộng sản Đông Dương vào tháng 3-1935 bầu ai làm Tổng bí thư?",["Trần Phú","Nguyễn Văn Cừ","Lê Hồng Phong","Hà Huy Tập"],"c",""],[106,"Hội nghị Trung ương VII khóa XII đã ban hành Nghị quyết số 36 - NQ/TW ngày 22/10/2018 về",["Chiến lược phát triển bền vững kinh tế biển Việt Nam đến năm 2030, tầm nhìn đến năm 2045","Đổi mới mục tiêu, con đường đi lên xã hội chủ nghĩa","Đổi mới nội dung, phương thức hoạt động, tổ chức cán bộ và quan hệ giữa các tổ chức trong hệ thống chính trị","Tăng cường công tác bảo vệ, chăm sóc và nâng cao sức khỏe nhân dân trong tình hình mới"],"a",""],[107,"Nội dung \"tập trung ưu tiên hoàn thiện thể chế kinh tế thị trường định hướng xã hội chủ nghĩa\" được Đại hội Đảng lần thứ XIII xác định là:",["Hoàn thiện hệ thống luật pháp, cơ chế, chính sách","Ưu tiên chính sách phát triển kinh tế tư nhân","Ưu tiên chính sách phát triển kinh tế nhà nước","Tạo lập môi trường đầu tư, kinh doanh thuận lợi, lành mạnh, công bằng cho mọi thành phần kinh tế"],"ad",""],[108,"Một trong những bài học về kinh tế mà Đảng rút ra trong 10 năm đổi mới đất nước 1986-1996 là",["Xây dựng kinh tế bao cấp","Xây dựng kinh tế Hợp tác xã","Xây dựng kinh tế tư nhân","Xây dựng nền kinh tế hàng hóa nhiều thành phần vận hành theo cơ chế thị trường"],"d",""],[109,"Cuộc kháng chiến chống thực dân Pháp xâm lược của nhân dân Đông Dương (1953 - 1954) kết thúc bằng giải pháp",["chính trị","quân sự","kinh tế","văn hóa"],"a",""],[110,"Sau Cách mạng tháng Tám đến 1954, kẻ thù chính của nhân dân Việt Nam là :",["Pháp","Anh","Mĩ","Trung quốc"],"a",""],[111,"Đại hội nào được đánh giá là Đại hội đổi mới đất nước?",["Đại hội IV 1976","Đại hội V 1982","Đại hội VI 1986","Đại hội VII 1991"],"c",""],[112,"Đặc điểm nổi bật của nước ta sau 1954 là :",["Đánh đuổi thực dân Pháp và can thiệp Mỹ xâm lược, giành độc lập dân tộc","Cả nước quá độ đi lên chủ nghĩa xã hội","Phát triển chế độ dân chủ nhân dân, gây cơ sở cho chủ nghĩa xã hội","Tiến hành động thời cách mạng xã hội chủ nghĩa ở miền Bắc và cách mạng dân tộc dân chủ nhân dân ở miền Nam"],"d",""],[113,"Tác động của chương trình khai thác thuộc địa lần thứ hai của Pháp đến kinh tế Việt Nam làm cho :",["Cơ cấu kinh tế Việt Nam mất cân đối, lạc hậu, nghèo nàn","Nền kinh tế Việt Nam phát triển độc lập","Kinh tế Việt Nam phát triển một cách tự chủ","Kinh tế Việt Nam phụ thuộc kinh tế Pháp"],"a",""],[114,"Mối quan hệ giữa hai khẩu hiệu: \"Độc lập dân tộc\" và \"Ruộng đất cho dân cày\" được giải quyết như thế nào trong thời kì 1939 - 1945?",["Tạm gác lại khẩu hiệu cách mạng ruộng đất.","Tạm gác lại khẩu hiệu cách mạng giải phóng dân tộc.","Tiếp tục thực hiện hai khẩu hiệu trên một cách đồng bộ.","Tạm gác lại việc thực hiện hai khẩu hiệu trên."],"a",""],[115,"Tác hại nào do cơ chế quản lý kinh tế tập trung, quan liêu, bao cấp vẫn tồn tại đến ngày nay và rất khó xóa bỏ?",["Không tạo được động lực phát triển.","Không thúc đẩy sản xuất phát triển","Làm giảm năng suất, chất lượng, hiệu quả.","Nhiều hiện tượng tiêu cực trong xã hội."],"d",""],[116,"Mỹ Ngụy không thực thi hiệp định Giơ-ne-vơ bằng cách :",["Ngăn cản hiệp thương, tổng tuyển cử thống nhất đất nước","Ban hành Luật 10/59","Thực hiện chiến dịch lập ấp chiến lược","Các phương án trả lời đều đúng"],"d",""],[117,"Điểm khác biệt về phương pháp đấu tranh của thời kì 1936 - 1939 so với thời kì 1930 - 1931 là",["Chính trị và vũ trang","Nghị trường và đấu tranh báo chí","Đấu tranh chính trị","Ngoại giao với vận động quần chúng"],"b",""],[118,"Cách mạng tháng Mười Nga thành công (1917) và Quốc tế Cộng sản ra đời (1919) có ý nghĩa:",["Đánh dấu sự thành công của cách mạng vô sản trên thế giới","Thức tỉnh phong trào đấu tranh của giai cấp công nhân ở các nước đế quốc","Thúc đẩy cuộc đấu tranh giai cấp ở các nước thuộc địa, phụ thuộc","Thức tỉnh phong trào đấu giải phóng dân tộc ở các nước thuộc địa, phụ thuộc"],"d",""],[119,"So với phong trào 1930 - 1931, điểm khác biệt về phương pháp đấu tranh của thời kì 1936 - 1939 là",["Kết hợp đấu tranh nghị trường và đấu tranh kinh tế.","Kết hợp đấu tranh ngoại giao với vận động quần chúng.","Kết hợp đấu tranh chính trị và đấu tranh vũ trang.","Kết hợp đấu tranh công khai và nửa công khai."],"c",""],[120,"Khi nói về triển vọng của cuộc kháng chiến chống Pháp, Đảng xác định trong Đường lối kháng chiến là :",["Mặc dù lâu dài, gian khổ, khó khăn song nhất định thắng lợi","Mặc dù phải hy sinh to lớn đến đâu nhưng nhất định sẽ thành công","Mặc dù bị bao vây và chưa được nước nào trên thế giới công nhận, song nhất định thắng lợi","Nhờ có sự hy sinh to lớn của dân tộc nên cuộc kháng chiến sẽ thành công"],"a",""],[121,"Mặt trận dân tộc thống nhất phản đế Đông Dương được thành lập vào thời gian nào?",["10-1930","5-1935","11-1939","5-1941"],"c",""],[122,"\"Trong lúc này nếu không giải quyết được vấn đề dân tộc giải phóng, không đòi được độc lập tự do cho toàn thể dân tộc, thì chẳng những toàn thể quốc gia dân tộc còn chịu mãi kiếp ngựa trâu mà quyền lợi của bộ phận giai cấp đến vạn năm cũng không đòi lại được\". Luận điểm trên được đưa ra tại Hội nghị nào của Đảng?",["Hội nghị Ban Chấp hành Trung ương tháng 11/1939","Hội nghị Cán bộ Trung ương tháng 11/1940","Hội nghị Ban Chấp hành Trung ương tháng 5/1941","Hội nghị Ban Thường vụ Trung ương tháng 3/1945"],"c",""],[123,"Hội nghị Trung ương VII khóa IX tháng 3/2003 đã thống nhất coi:",["Đất đai là tài nguyên quốc gia vô cùng quý giá","Đất đai là tài nguyên quốc gia vô cùng quý giá, là tư liệu đặc biệt, là nguồn nội lực và nguồn vốn to lớn của đất nước","Công nghiệp hóa được nhận thức là \"công nghiệp hóa- hiện đại hóa gắn với phát triển kinh tế tri thức\"","Công nghiệp hóa được nhận thức là \"công nghiệp hóa- hiện đại hóa gắn với phát triển kinh tế tri thức trong cơ chế thị trường định hướng XHCN và hội nhập kinh tế quốc tế\""],"b","(Kiểu hỏi khác: Hội nghị Trung ương VII khóa IX tháng 3/2003 đã thống nhất coi: A. Đất đai là tài nguyên quốc gia vô cùng quý giá, là tư liệu đặc biệt, là nguồn nội lực và nguồn vốn to lôn của đất nước B. Đối mỗi tố chức và phương thức hoạt động của hệ thống chính trị làm cho nó phủ hợp với đường lối đối môi toàn diện, đông bộ đất nước C. Đối mới hệ thống chính trị một cách toàn diện, đồng bộ có kế thừa, có bước đi hình thức và cách làm phù hợp D. Đối mới quan hệ giữa các bộ phận cấu thành của hệ thống chính trị với nhau và với xã hội là rất quan trọng)"],[124,"Từ 1961-1965, Mĩ thực hiện loại hình chiến lược nào ở miền Nam Việt Nam?",["Chiến tranh đơn phương","Chiến tranh đặc biệt","Chiến tranh cục bộ","Việt Nam hóa chiến tranh"],"b",""],[125,"Nội dung nào trong Hiệp định Sơ bộ 6-3-1946 tạo điều kiện cho ta có thời gian để chuẩn bị lực lượng đối phó lâu dài với Pháp?",["Pháp công nhận Việt Nam là một quốc gia tự do trong khối liên hiệp Pháp.","Pháp được đưa 15 ngàn quân ra miền Bắc thay thế quân Tưởng","Hai bên ngừng bắn ở Nam Bộ","Hai bên thực hiện tập kết, chuyển quân"],"c",""],[126,"Mặt trận Dân tộc giải phóng miền Nam Việt Nam được thành lập ở đâu?",["Bến Tre","Tây Ninh","Bình Định","Tây Nguyên"],"b",""],[127,"Mô hình kinh tế thị trường định hướng xã hội chủ nghĩa ở nước ta được chính thức nêu ra ở Đại hội nào của Đảng?",["Đại hội VI","Đại hội VII","Đại hội VIII","Đại hội IX"],"d","(Kiểu hỏi khác: Khái niệm \"kinh tế thị trường định hướng xã hội chủ nghĩa\" được Đảng đưa vào văn kiện lần đầu tiên ở Đại hội nào?)"],[128,"Quan điểm quan trọng về giải quyết các vấn đề xã hội thời kỳ đổi mới là:",["Ưu tiên mục tiêu xã hội trên mục tiêu kinh tế","Kết hợp các mục tiêu kinh tế với các mục tiêu xã hội","Chú trọng các mục tiêu kinh tế, từng bước thực hiện mục tiêu xã hội","Thực hiện mục tiêu xã hội trên cơ sở thực hiện thắng lợi các mục tiêu kinh tế"],"b",""],[129,"Trong lịch sử Đảng Cộng sản Việt Nam, giai đoạn 1932 - 1935 là giai đoạn",["Chuẩn bị các điều kiện để giành chính quyền","Phục hồi hệ thống tổ chức của Đảng","Đẩy mạnh phong trào đấu tranh","Hợp tác với phong trào nhân dân Pháp"],"b",""],[130,"Một trong những nội dung mới của Đại hội Đảng lần thứ X là:",["Xây dựng, chỉnh đốn Đảng là nhiệm vụ then chốt hàng đầu và cho phép đảng viên làm kinh tế tư nhân.","Xây dựng chủ nghĩa xã hội","Xây dựng hệ thống chính trị","Xây dựng kinh tế tư nhân"],"a",""],[131,"Hội nghị Trung ương V khóa X tháng 7/2007 ban hành Nghị quyết số 14- NQ/TW về :",["Tăng cường công tác kiểm tra, giám sát của Đảng","Tăng cường công tác kiểm tra, giám sát của đoàn thể","Cương lĩnh xây dựng đất nước","Thay đổi hệ thống chính trị"],"a",""],[132,"Đại hội Đảng lần thứ IV (12/1976) quyết định đổi tên Đảng thành:",["Đảng Lao động Việt Nam","Đảng Cộng sản Việt Nam","Đảng Cộng sản Đông Dương","Đảng nhân dân cách mạng Việt Nam"],"b","(Kiểu hỏi khác: Đại hội lần thứ IV của Đảng họp từ 14 - 20/12/1976 tại Hà Nội quyết định đổi tên Đảng thành)"],[133,"Lê Hồng Phong được bầu làm Tổng bí thư tại Đại hội nào của Đảng?",["Đại hội đại biểu toàn quốc lần thứ II","Đại hội đại biểu toàn quốc lần thứ III","Đại hội đại biểu toàn quốc lần thứ I","Đại hội đại biểu toàn quốc lần thứ IV"],"c",""],[134,"Tổ chức Cộng sản nào ra đời đầu tiên ở Việt Nam?",["Hội Việt Nam cách mạng Thanh Niên","Đông Dương Cộng sản Đảng","An Nam Cộng sản đảng","Đông Dương Cộng sản liên đoàn"],"b",""],[135,"Sự kiện lịch sử nào mở ra tiền đề để Việt Nam thúc đẩy quan hệ với khu vực và cộng đồng quốc tế?",["Bình thường hóa quan hệ với Trung Quốc","Việt Nam tham gia ký Hiệp định Pari (23/10/1991) về một giải pháp toàn diện cho vấn đề Campuchia","Bình thường hóa quan hệ với Hoa Kỳ","Việt Nam gia nhập hiệp hội các nước Đông Nam Á (Asean)"],"b",""],[136,"Nhân tố hàng đầu đảm bảo thắng lợi của cuộc kháng chiến chống Mĩ, cứu nước (1954-1975) là sự lãnh đạo của Đảng Cộng sản Việt Nam vì Đảng",["tranh thủ được sự giúp đỡ của các nước xã hội chủ nghĩa.","có đường lối cách mạng đúng đắn, sáng tạo, độc lập tự chủ.","lãnh đạo xây dựng miền Bắc thành hậu phương vững mạnh.","đã kết hợp sức mạnh toàn dân tộc với sức mạnh của thời đại."],"b",""],[137,"Trung ương nhận định như thế nào về Chiến lược kinh tế Biển ở thế kỉ XXI?",["Biển là tiềm năng kinh tế to lớn của đất nước","Việt Nam phải là quốc gia mạnh về biển","Việt Nam phải trở thành quốc gia mạnh về biển, làm giàu từ biển","Việt Nam phải trở thành quốc gia mạnh về biển, làm giàu từ biển, trên cơ sở phát huy mọi tiềm năng từ biển, phát triển toàn diện các ngành, nghề biển"],"d",""],[138,"Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên Chủ nghĩa xã hội (bổ sung, phát triển năm 2011) đã bổ sung đặc trưng của xã hội chủ nghĩa mà nhân dân ta xây dựng. Điểm bổ sung đó là:",["Con người có cuộc sống ấm no, tự do, hạnh phúc, có điều kiện phát triển toàn diện","Các dân tộc trong cộng đồng Việt Nam bình đẳng, đoàn kết, tôn trọng và giúp đỡ nhau cùng phát triển","Có quan hệ hữu nghị và hợp tác với các nước trên thế giới","Có nhà nước pháp quyền xã hội chủ nghĩa của nhân dân, do nhân dân, vì nhân dân do Đảng Cộng Sản lãnh đạo.","Có ý thức tự giác, tính nhân đạo, tinh thần trách nhiệm cao, hết lòng vì cộng đồng."],"d","(Kiểu hỏi khác: Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (bổ sung, phát triển năm 2011) đã sung đặc trưng của xã hội xã hội chủ nghĩa mà nhân dân ta xây dựng. Điểm bổ sung đó là: A. Có nên văn hóa tiên tiến, đậm đà bản sắc dân tộc B. Do nhân dân làm chủ C. Dân giảu, nước mạnh, dân chủ, công bằng, văn minh D. Có nên kinh tế phát triển cao dựa trên lực lượng sản xuất hiện đại và quan hệ sản xuất tiến bộ, phù hợp)"],[139,"Quyền dân tộc cơ bản của Việt Nam trong Hiệp định Giơnevơ 1954 là gì?",["Độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ","Các bên thực hiện cuộc tập kết, chuyển quân, chuyển giao khu vực","Việt Nam sẽ tiến hành tổng tuyển cử thống nhất đất nước","Các bên tham chiến thực hiện ngừng bắn, lập lại hòa bình ở Đông Dương"],"a",""],[140,"Trong các nội dung sau đây, nội dung nào không thuộc luận cương chính trị tháng 10/1930?",["Cách mạng Việt Nam phải trải qua hai giai đoạn: cách mạng tư sản dân quyền và cách mạng xã hội chủ nghĩa","Cách mạng do Đảng của giai cấp vô sản lãnh đạo","Cách mạng Việt Nam là một bộ phận của cách mạng thế giới","Lực lượng để đánh đuổi đế quốc và phong kiến là công nông. Đồng thời \"phải biết liên lạc với tiểu tư sản, tri thức, trung nông ... để kéo họ về phe vô sản giai cấp\""],"d",""],[141,"Chiến dịch lịch sử Điện Biên Phủ 1954 là đỉnh cao của :",["Khởi nghĩa chống Pháp","Kháng chiến chống Pháp","Kháng chiến chống Mĩ","Chiến tranh chống Pháp"],"b",""],[142,"Một trong những nội dung của chương trình hành động của Đảng Cộng sản Đông Dương là :",["Cải cách ruộng đất","Cải cách giáo dục","Đòi tự do, bình đẳng","Đoì quyêǹ tư do: Phát ngôn, tư do đi lạ i..."],"d",""],[143,"Phong trào Xô Viết Nghệ Tĩnh được bắt đầu từ ngày tháng năm nào?",["1 - 5 - 1930","1 - 5 - 1931","19 - 5 - 1930","19 -8 - 1930"],"a",""],[144,"Nghị quyết Hội nghị Trung ương lần thứ 15 (1/1959) đánh dấu sự thay đổi chiến lược trong chỉ đạo cách mạng miền Nam ở điểm nào?",["Chuyển cách mạng miền Nam sang đấu tranh đòi quyền tự do dân chủ","Kết hợp đấu tranh chính trị với đấu tranh quân sự, tiến tôi khởi nghĩa vũ trang giành chính quyền về tay nhân dân","Sử dụng đấu tranh chính trị giành chính quyền về tay nhân dân","Tập trung lực lượng chính trị, lực lượng vũ trang đấu tranh giành độc lập dân tộc"],"b",""],[145,"Thời gian từ tháng 3 năm 1946 đến ngày 19/12/1946, Đảng lãnh đạo nhân dân thực hiện chủ trương chiến lược:",["Hòa để tiến","Đối đầu với quân đội Pháp","Đối đầu với quân đội Tưởng","Giải giáp quân đội Nhật"],"a",""],[146,"Đại hội lần thứ V của Đảng (1982) đã coi lĩnh vực nào là Mặt trận hàng đầu?",["Công nghiệp","Nông nghiệp","Thương nghiệp","Dịch vụ"],"b",""],[147,"Đối tượng của cách mạng Việt Nam được xác định trong Cương lĩnh chính trị đầu tiên của Đảng (2/1930) là :",["Phong kiến, đế quốc","Đế quốc, tư sản phản cách mạng","Thực dân Pháp và tư sản mại bản","Đế quốc, phong kiến và tư sản phản cách mạng"],"d",""],[148,"Xây dựng Đảng ngang tầm với thời kì Công nghiệp hóa- Hiện đại hóa đất nước đòi hỏi :",["Thực hiện tốt hơn dân chủ xã hội chủ nghĩa, phát huy đầy đủ quyền làm chủ của nhân dân.","Thực hiện tốt hơn dân chủ xã hội chủ nghĩa, phát huy đầy đủ quyền tự do của nhân dân.","Thực hiện tốt hơn dân chủ xã hội chủ nghĩa, phát huy đầy đủ quyền giám sát của nhân dân.","Đảng phải tiếp tục tự đổi mới, tự chỉnh đốn, nâng cao hơn nữa sức chiến đấu và năng lực lãnh đạo của mình, khắc phục cho được các biểu hiện tiêu cực và yếu kém."],"d",""],[149,"Trước sự xâm lược của thực dân Pháp, phong trào yêu nước do Việt Nam quốc dân Đảng khởi xướng theo khuynh hướng nào sau đây:",["Khuynh hướng phong kiến","Khuynh hướng vô sản","Khuynh hướng dân chủ tư sản","Khuynh hướng tiểu tư sản"],"c",""],[150,"Đường lối toàn quốc kháng chiến tập trung trong ba văn kiện quan trọng đó là:",["Toàn dân kháng chiến, Lời kêu gọi toàn quốc kháng chiến, Kháng chiến nhất định thắng lợi","Nhật Pháp bắn nhau và hành động của chúng ta, Kháng chiến kiến quốc, Kháng chiến nhất định thắng lợi","Toàn dân kháng chiến, Nhật Pháp bắn nhau và hành động của chúng ta, Kháng chiến kiến quốc","Lời kêu gọi toàn quốc kháng chiến, Nhật Pháp bắn nhau và hành động của chúng ta, Kháng chiến kiến quốc"],"a",""],[151,"Công nghiệp hóa- Hiện đại hóa đất nước là sự nghiệp của :",["Toàn dân","Đảng Cộng sản Việt Nam","Cơ quan quản lý nhà nước về văn hóa","Nhà nước Việt Nam"],"a",""],[152,"Chủ đề của Đại hội Đảng lần thứ X từ ngày 18 - 25/4/2006 tại Hà Nội là",["Nâng cao năng lực lãnh đạo và sức chiến đấu của Đảng, phát huy sức mạnh toàn dân tộc","Nâng cao năng lực lãnh đạo, phát triển công nghiệp hóa- hiện đại hóa đất nước","Phát triển và hội nhập quốc tế","Nâng cao năng lực lãnh đạo và sức chiến đấu của Đảng, phát huy sức mạnh toàn dân tộc, đẩy mạnh toàn diện công cuộc đổi mới sớm đưa nước ta ra khỏi tình trạng kém phát triển"],"d",""],[153,"Nội dung nào không đúng trong đặc trưng chủ yếu của đường lối công nghiệp hoá thời kỳ trước đổi mới?",["Chủ yếu dựa vào lợi thế về lao động, tài nguyên, đất đai và nguồn viện trợ của các nước xã hội chủ nghĩa","Công nghiệp hóa theo mô hình nền kinh tế khép kín hướng nội và thiên về phát triển công nghiệp nặng.","Chủ lực thực hiện công nghiệp hóa là Nhà nước và các doanh nghiệp nhà nước.","Việc phân bổ nguồn lực để công nghiệp hóa thực hiện thông qua cơ chế hạch toán kinh doanh xã hội chủ nghĩa"],"d","(Kiểu hỏi khác: Nội dung nào không đúng trong đặc trưng chủ yếu của đường lối công nghiệp hoá thời kỳ trước đổi mới? a. Nóng vội, giản đơn, duy ý chí, ham làm nhanh, làm lớn, không quan tâm đến hiệu quả kinh tế - xã hội. b. Công nghiệp hóa theo mô hình nền kinh tế khép kín hướng nội và thiên về phát triển công nghiệp nặng. c. Chủ lực thực hiện công nghiệp hóa là Nhà nước và các doanh nghiệp nhà nước. d. Công nghiệp hóa được thực hiện thông qua cơ chế thị trường định hướng xã hội chủ nghĩa.)"],[154,"Sự kiện lịch sử nào dưới đây diễn ra trong phong trào dân tộc dân chủ ở Việt Nam từ 1925 đến 1930?",["Bãi công của công nhân Ba Son","Bãi công của công nhân Vinh-Bến Thủy","Phong trào Đông Dương đại hội","Phong trào phá kho thóc của Nhật"],"a",""],[155,"Trong thời kỳ 1954-1975, cuộc cách mạng dân tộc dân chủ nhân dân ở miền Nam Việt Nam có vai trò quyết định trực tiếp đối với sự nghiệp giải phóng miền Nam vì cuộc cách mạng này",["Bảo vệ vững chắc hậu phương miền Bắc xã hội chủ nghĩa.","Làm thất bại hoàn toàn chiến lược toàn cầu của Mỹ.","Trực tiếp xóa bỏ ách áp bức, bóc lột của địa chủ và tư sản miền Nam.","Trực tiếp đánh đổ ách thống trị của Mỹ và chính quyền Sài Gòn"],"d",""],[156,"\"Đoàn kết, tập hợp lực lượng cách mạng nhằm giải phóng dân tộc\" là chủ trương của Đảng trong việc thành lập tổ chức nào?",["Mặt trận Việt Minh","Mặt trận dân chủ thống nhất phản đế Đông Dương","Mặt trận dân chủ Đông Dương","Hội phản đế đồng minh"],"a",""],[157,"Năm 1998, Việt Nam trở thành thành viên của :",["ASEAN","APEC","Liên Hợp Quốc","WTO"],"b",""],[158,"Nhân dân ta phải tiến hành tổng khởi nghĩa giành chính quyền trước khi quân Đồng minh vào Đông Dương vì:",["Đó là lúc so sánh lực lượng có lợi nhất đối với cách mạng","Đó là lúc kẻ thù cũ đã ngã gục nhưng kẻ thù mới chưa kịp đến","Quân Đồng minh có thể dựng ra một chính quyền trái với ý chí và nguyện vọng của nhân dân ta","Tất cả nhận định trên"],"d",""],[159,"Đại hội Đảng lần thứ II xác định nhiệm vụ của cách mạng Việt Nam là",["Đánh đuổi bọn đế quốc xâm lược, xóa bỏ những di tích phong kiến và nửa phong kiến, phát triển chế độ dân chủ nhân dân","Đánh đuổi bọn đế quốc xâm lược, giành độc lập thống nhất thật sự cho dân tộc, gây cơ sở cho chủ nghĩa xã hội","Đánh đuổi bọn đế quốc xâm lược, giành độc lập thống nhất thật sự cho dân tộc, làm cho người cày có ruộng, phát triển chế độ dân chủ nhân dân","Làm cho người cày có ruộng, gây cơ sở cho chủ nghĩa xã hội, phát triển chế độ dân chủ nhân dân"],"a","(Câu trả lời đúng phải là: Đánh đuổi bọn đế quốc xâm lược, giành độc lập và thống nhất thật sự cho dân tộc, xoá bỏ những di tích phong kiến và nửa phong kiến, làm cho người cày có ruộng, phát triển chế độ dân chủ nhân dân, gây cơ sở cho chủ nghĩa xã hội.)"],[160,"Quốc tế cộng sản (Quốc tế III) được thành lập vào năm nào?",["1918","1919","1920","1921"],"b",""],[161,"Nghị quyết Trung ương III, tháng 6/1997 đã chú trọng nội dung nào sau đây?",["Làm chủ của nhân dân","Lãnh đạo của Đảng","Của các tổ chức chính trị-xã hội","Của Mặt trận tổ quốc"],"a",""],[162,"Hiệp định sơ bộ được Hồ Chí Minh ký với Sanh-tơ-ny vào thời gian nào sau đây?",["6/3/1946","14/9/1946","19/12/1946","10/12/1946"],"a",""],[163,"Cuộc tập dượt thứ nhất của Đảng chuẩn bị cho thắng lợi của cách mạng tháng Tám là giai đoạn :",["1930-1931","1936-1939","1939-1945","1945-1954"],"a",""],[164,"Để tranh thủ thời gian chống Pháp, Đảng chủ trương quan hệ với quân Tưởng Giới Thạch theo khẩu hiệu :",["Hoa Việt thân thiện","Hoa Việt bình đẳng","Hoa Việt tương trợ","Hoa Việt thân ái"],"a",""],[165,"Đại hội lần thứ VII của Quốc tế Cộng sản họp vào năm nào?",["1936","1930","1935","1939"],"c",""],[166,"Khẩu hiệu của Đại hội lần thứ XII của Đàng là :",["Đoàn kết - Dân chủ-Kỷ cương - Đổi mới","Đẩy mạnh toàn diện đồng bộ công cuộc đổi mới","Tăng cường khối Đại đoàn kết toàn dân tộc","Xây dựng Đảng trong sạch, vững mạnh"],"a",""],[167,"Hội nghị Trung ương III, khóa VIII tháng 12/1996 đã chủ trương.",["Xây dựng đội ngũ cán bộ các cấp có phẩm chất và năng lực, có bản lĩnh chính trị vững vàng, đủ về số lượng, đồng bộ về cơ cấu","Phát triển khoa học và công nghệ trong giai đoạn hiện nay","Phát triển giáo dục và đào tạo trong giai đoạn hiện nay","Xây dựng kinh tế trong giai đoạn hiện nay"],"a",""],[168,"\"Tranh thủ được nguồn viện trợ đáng kể, góp phần khôi phục đất nước sau chiến tranh\" là một trong những ý nghĩa của ngoại giao Việt Nam thời kỳ nào?",["Sau đổi mới (1975-1985)","Trước đổi mới (1945-1985)","Sau đổi mới (1985 - 1995)","Trước đổi mới (1975-1985)"],"d",""],[169,"Căn cứ địa cách mạng đầu tiên của Việt Nam trong giai đoạn 1939-1945 là :",["Cao Bằng","Bắc Sơn - Võ Nhai","Thái Nguyên","Tuyên Quang"],"b",""],[170,"Chống phát xít, chống chiến tranh đế quốc, chống bọn phản động thuộc địa và tay sai là nhiệm vụ cách mạng được Đảng đề ra trong giai đoạn nào?",["1930 - 1931","1936-1939","1939 - 1945","1945-1954"],"b",""],[171,"Mặt trận được xây dựng thời kỳ cách mạng 1930- 1931 gọi tên là:",["Mặt trận nhân dân phản đế Đông Dương","Mặt trận dân chủ Đông Dương","Hội phản đế Đông Dương","Mặt trận dân tộc thống nhất phản đế Đông Dương"],"c",""],[172,"Điểm giống nhau giữa Luận cương chính trị 10-1930 và Cương lĩnh chính trị đầu tiên của Đảng tháng 2-1930 là:",["Khẳng định vai trò lãnh đạo cách mạng của Đảng Cộng sản","Xác định nhiệm vụ cách mạng là chống đế quốc, phong kiến","Ảnh hưởng quan trọng đối với cách mạng Đông Dương","Xác định lực lượng là công- nông"],"a",""],[173,"Nhiệm vụ trung tâm của thời kỳ quá độ xây dựng đất nước là:",["Đẩy mạnh Công nghiệp hóa xã hội chủ nghĩa","Hợp tác xã nông nghiệp theo định hướng xã hội chủ nghĩa","Kinh tế thị trường định hướng xã hội chủ nghĩa","Nắm vững các quy luật kinh tế của chủ nghĩa xã hội."],"a","(Kiểu hỏi khác: Đại hội lần thứ III của Đảng (1960) xác định nhiệm vụ trung tâm trong suốt thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam là: A. Cách mạng văn hóa tư tưởng B. Công nghiệp hóa xã hội chủ nghĩa C. Cải tạo xã hội chủ nghĩa đối với nông nghiệp, thủ công nghiệp D. Phát triển kinh tế quốc doanh)"],[174,"Chính cương của Đảng lao động Việt Nam đã nêu ra các nhiệm vụ cơ bản của cách mạng Việt Nam là:",["Đánh đuổi bọn đế quốc xâm lược, giành độc lập và thống nhất thật sự cho dân tộc; Xóa bỏ những di tích phong kiến và nửa phòng kiến, làm cho người cày có ruộng; Phát triển chế độ dân chủ nhân dân, gây cơ sở cho chủ nghĩa xã hội","Đánh đuổi bọn đế quốc xâm lược, giành độc lập và thống nhất thật sự cho dân tộc; Xóa bỏ những di tích phong kiến và nửa phòng kiến, làm cho người cày có ruộng; Phát triển chế độ dân chủ nhân dân, gây cơ sở cho xã hội dân chủ.","Đánh đuổi bọn phong kiến, giành độc lập và thống nhất thật sự cho dân tộc; Xóa bỏnhững di tích phong kiến và nửa phòng kiến, làm cho người"],"a",""],[175,"So với chiến dịch Điện Biên Phủ 1954 với chiến dịch Hồ Chí Minh 1975 có khác gì về kết quả và ý nghĩa?",["Đã đập tan hoàn toàn kế hoạch quân sự của địch","Giải phóng hoàn toàn miền Bắc tạo tiền đề hoàn thành cuộc cách mạng dân chủ nhân dân trong cả nước","Làm xoay chuyển cục diện chiến tranh, tạo điều kiện thuận lợi để giành thắng lợi cuối cùng","Là dấu mốc kết thúc cuộc chiến tranh giải phóng dân tộc, bảo vệ Tổ quốc, chấm dứt ách thống trị của thực dân đế quốc"],"d",""],[176,"Đoàn đại biểu miền Nam do ai dẫn đầu để thống nhất hiệp thương với miền Bắc sau năm 1975?",["Phạm Hùng","Châu Văn Liêm","Trường Chinh","Phạm Hữu Thọ"],"a",""],[177,"Phong trào mà Đảng ta đã vận động nhân dân chống nạn mù chữ diễn ra sau cách mạng tháng Tám năm 1945 là :",["Xây dựng nếp sống văn hoá mới","Bình dân học vụ","Bài trừ các tệ nạn xã hội","Xoá bỏ văn hoá thực dân nô dịch phản động"],"b",""],[178,"Đại hội lần thứ VIII của Đảng chủ trương tăng trưởng kinh tế gắn liền với tiến bộ và công bằng xã hội trong điều kiện nào?",["Trong cả thời kỳ quá độ và suốt quá trình phát triển","Trong từng bước và suốt quá trình phát triển","Trong riêng thời kỳ quá độ và suốt quá trình phát triển","Trong từng bước và suốt quá trình xây dựng thể chế kinh tế thị trường"],"b",""],[179,"Hội nghị Trung ương 3 khóa X ban hành Nghị quyết số 04-NQ/TW ngày 21/8/2006 về",["Mở rộng thị trường, trao đổi hàng hóa tăng mạnh đã thúc đẩy sản xuất hàng hóa của các nước","Nguồn vốn, khoa học công nghệ, kinh nghiệm quản lý cùng các hình thức đầu tư, hợp tác mang lại lợi ích cho các bên","Tăng cường sự lãnh đạo của Đảng với công tác đấu tranh phòng, chống tham nhũng lãng phí","Các nước công nghiệp phát triển thao túng, chi phối quá trình toàn cầu hóa tạo ra sự bất bình đẳng trong quan hệ quốc tế và làm gia tăng sự phân cực giữa nước giàu và nghèo"],"c",""],[180,"Ngày 12/12/1946, Ban Thường vụ Trung ương Đảng đã ra",["Quân lệnh số 1.","Lời kêu gọi Tổng khởi nghĩa.","Chỉ thị Toàn dân kháng chiến.","Lời kêu gọi toàn quốc kháng chiến."],"c",""],[181,"\"Chúng ta thà hi sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ...\" là đoạn trích trong văn kiện nào?",["Chỉ thị Toàn dân kháng chiến của Ban Thường vụ Trung ương Đảng","Lời kêu gọi toàn quốc kháng chiến của Chủ tịch Hồ Chí Minh","Tác phẩm Kháng chiến nhất định thắng lợi của Tổng Bí thư Trường Chinh","Chi thị sửa soạn khởi nghĩa của Tổng bộ Việt Minh"],"b","(Kiểu hỏi khác: Lời kêu gọi toàn quốc kháng chiến của Chủ tịch Hồ Chí Minh được phát ra vào thời gian nào? a. 12-12-1946 b. 22-12-1946 c. 2-3-1946 d. 19-12-1946)"],[182,"Hiệp định Giơnevơ 1954, quy định việc di chuyển, tập kết quân đội ở hai miền Nam - Bắc với giới tuyến quân sự tạm thời là :",["Vĩ tuyến 17","Vĩ tuyến 18","Vĩ tuyến 19","Vĩ tuyến 20"],"a",""],[183,"Cuộc kháng chiến chống Mĩ, cứu nước của nhân dân ta là một cuộc đụng đầu lịch sử vì:",["Đây là cuộc đấu tranh của một dân tộc nhược tiểu chống lại một đế quốc số một thế giới.","Đây là một cuộc chiến tranh xâm lược, phi nghĩa đứng về phía Mĩ - một đại diện cho chủ nghĩa đế quốc.","Đây là một cuộc chiến phản ánh tập trung những mâu thuẫn cơ bản của thời đại.","Đây là một cuộc chiến tranh chống chủ nghĩa thực dân mới của Mĩ, thực hiện giải phóng dân tộc, thống nhất đất nước đầu tiên giành thắng lợi."],"c",""],[184,"Nội dung nào không có trong Hội nghị Trung ương VIII của Đảng (tháng 5 năm 1941)?",["Đưa nhiệm vụ giải phóng dân tộc lên hàng đầu.","Chuẩn bị điều kiện để \"đánh đổ địa chủ, chia ruộng đất cho dân cày\".","Thành lập mặt trận Việt Minh để tập hợp lực lượng cách mạng nhằm mục tiêu giải phóng dân tộc.","Xác định chuẩn bị khởi nghĩa là nhiệm vụ trung tâm trong giai đoạn hiện tại"],"b",""],[185,"Một trong những nhiệm vụ chiến lược mà Đại hội lần thứ V của Đảng khẳng định là :",["Đảm bảo quyền lực thuộc về nhân dân","Xây dựng lực lượng cho Đảng Cộng sản Việt Nam","Bảo vệ vững chắc Tổ quốc Việt Nam xã hội chủ nghĩa","Xây dựng nhà nước pháp quyền Việt Nam xã hội chủ nghĩa"],"c",""],[186,"Tổ chức tổng tuyển cử trên toàn lãnh thổ Việt Nam bầu ra Quốc hội chung cho cả nước vào đầu năm 1976 theo nguyên tắc nào?",["Dân chủ phổ thông, bình đẳng trực tiếp và bỏ phiếu kín","Hoàn tuân thể chế về chính trị và ổn định về kinh tế","Hoàn thiện thể chế đảm bảo đồng bộ các yếu tố thị trưởng và phát triển động bố các loại thị trường","Hoàn thiện thể chế gắn tăng trưởng kinh tế với tiến bộ, công bằng xã hội và bảo vệ môi trường"],"a",""],[187,"Nhiệm vụ của cách mạng Việt Nam được xác định trong Luận cương chính trị tháng 10/1930 do Trần Phú soạn thảo là :",["đánh đổ phong kiến và đế quốc","giải phóng dân tộc.","đánh đổ đế quốc và tay sai","đánh đổ đế quốc Pháp, phong kiến và tư sản phản cách mạng, làm cho nước Việt Nam độc lập tự do."],"a",""],[188,"Cương lĩnh Đại hội Đảng lần thứ 11 diễn ra từ 12 - 19/1/2011 nêu rõ: Xã hội xã hội chủ nghĩa mà nhân dân ta xây dựng là một xã hội:",["Của dân, do dân, vì dân","Của dân, do dân, vì dân có nền kinh tế phát triển","Dân giàu, nước mạnh, dân chủ, công bằng, văn minh","Dân giàu, nước mạnh, dân chủ, công bằng, văn minh do nhân dân làm chủ"],"d",""],[189,"Tại hội nghị nào, Ban Chấp hành Trung ương Đảng quyết định để nhân dân miền Nam sử dụng bạo lực cách mạng đánh đổ chính quyền Mĩ- Diệm?",["Hội nghị Trung ương lần thứ 15 (1-1959)","Hội nghị Trung ương lần thứ 11 (3-1965)","Hội nghị Trung ương lần thứ 12 (12-1965)","Hội nghị Trung ương lần thứ 21 (7/1973)"],"a",""],[190,"Sau khi giành chính quyền, Đảng chủ trương mở rộng mặt trận nào sau đây để tập trung ngọn lửa đấu tranh chống Pháp?",["Mặt trận Việt Minh","Mặt trận Liên Việt","Mặt trận Dân chủ","Mặt trận tổ quốc Việt Nam"],"a",""],[191,"Đường lối toàn quốc kháng chiến của Đảng vạch ra mục tiêu của kháng chiến là:",["Đánh phản động thực dân Pháp xâm lược, giành thống nhất và độc lập","Đánh phản động phát xít Nhật xâm lược, giành thống nhất và độc lập","Đánh phản động đế quốc Mỹ xâm lược, giành thống nhất và độc lập","Đánh phản động Trung Hoa Dân Quốc xâm lược, giành thống nhất và độc lập"],"a",""],[192,"Thắng lợi của cuộc kháng chiến chống Mỹ cứu nước đã cho ta nhiều bài học quý, bài học nào dưới đây là chưa phù hợp với thời kỳ chống Mỹ?",["Giương cao ngọn cờ độc lập dân tộc và dân chủ","Kiên định tư tưởng chiến lược tiến cũng quyết đánh và quyết thắng đế quốc Mỹ xâm lược","Thực hiện chiến tranh nhân dân linh hoạt sáng tạo","Coi trọng công tác tổ chức, công tác xây dựng Đảng"],"a",""],[193,"Hội nghị Trung ương VI khóa XII Ban hành Nghị quyết số 20-NQ/TW ngày 25/10/2007 về :",["Công tác dân số trong tình hình mới.","Xây dựng văn hóa trong tình hình mới","Hội nhập trong tình hình mới","Tăng cường công tác bảo vệ, chăm sóc và nâng cao sức khỏe nhân dân trong tình hình mới."],"d",""],[194,"Công lao to lớn đâù tiên của Nguyêñ Ái Quốc đối với cách mạng Viêt Nam la ̀gì?",["Tim̀ đươc con đươǹg cứu nước đúng đ ắn","Thaǹh lâp Hôi Viêt Nam Caćh mạng than h niên","Chủ trì Hội nghị thaǹh Đan̉g công san̉ V iêt Nam","Thành lập Đông Dương cộng sản đảng"],"a",""],[195,"Nhận xét nào sau đây là phù hợp về Hội Việt Nam cách mạng Thanh niên (1925-1929)?",["Một trong những tổ chức cộng sản đầu tiên ở Việt Nam","Là đội tiên phong của giai cấp công nhân Việt Nam","Là tổ chức tiền thân của Đảng Cộng sản Việt Nam","Đại diện tiêu biểu của giai cấp tiểu tư sản Việt Nam"],"c",""],[196,"Điền vào chỗ trống. Mục tiêu cụ thể được nêu trong đại hội lần thứ XIII của Đảng đó là: \"Đến năm 2025, kỷ niệm 50 năm giải phóng hoàn toàn miền Nam, thống nhất đất nước: là nước đang phát triển, có công nghiệp theo hướng hiện đại, vượt qua mức thu nhập....\"",["Trung bình thấp","Trung bình cao","Trung bình","Trung bình kém phát triển"],"a",""],[197,"Đảng ta đã lựa chọn giải pháp gì trong mối quan hệ với thực dân Pháp sau ngày Pháp và Tưởng ký hiệp ước Trùng Khánh (28-2-1946)?",["Kháng chiến chống thực dân Pháp","Chống cả quân đội Tưởng và Pháp","Nhân nhượng với quân đội Tưởng","Thương lượng và hoà hoãn với Pháp"],"d",""],[198,"Ngày 23-9-1945 gắn với sự kiện lịch sử nào?",["Pháp nổ súng xâm lược nước ta lần thứ 2.","Bác ra lời kêu gọi toàn quốc kháng chiến.","Nhật đảo chính Pháp độc chiếm Đông Dương.","Hội nghị quốc dân ở Tân Trào"],"a",""],[199,"Đâu là luận điểm sáng tạo của Hồ Chí Minh khi vận dụng chủ nghĩa Mác - Lênin về việc ra đời của Đảng Cộng sản Việt Nam?",["Đảng Cộng sản Việt Nam ra đời là tất yếu lịch sử, nó là sản phẩm kết hợp giữa chủ nghĩa Mác với phong trào công nhân Việt Nam.","Đảng Cộng sản Việt Nam ra đời là tất yếu lịch sử, nó là sản phẩm kết hợp giữa chủ nghĩa Mác với phong trào yêu nước Việt Nam.","Đảng Cộng sản Việt Nam là sản phẩm của sự kết hợp chủ nghĩa Mác-Lênin với phong trào công nhân và phong trào yêu nước của nhân dân Việt Nam.","Đảng Cộng sản Việt Nam là sản phẩm của sự kết hợp phong trào công nhân và phong trào yêu nước Việt Nam."],"c",""],[200,"Trong phong trào dân chủ 1936-1939, Nhân dân Việt Nam thực hiện một trong những nhiệm vụ trực tiếp, trước mắt là đấu tranh chống :",["Chế độ phản động thuộc địa","Đế quốc và chế độ phong kiến","Tư sản và địa chủ","Đế quốc và tư sản"],"a",""],[201,"Lực lượng chủ yếu tham gia phong trào cách mạng 1930-1931 ở Việt Nam là :",["Tiểu tư sản, công nhân","Nông dân, tiểu tư sản","Công nhân và nông dân","Nông dân, tư sản dân tộc."],"c",""],[202,"Lực lượng cách mạng được nêu ra trong Luận cương chính trị (tháng 10-1930) của Đảng Cộng sản Đông Dương là :",["Công nhân, nông dân và tư sản","Nông dân và tiểu tư sản","Công nhân, nông dân","Công nhân, nông dân và trí thức"],"c",""],[203,"Nguyên nhân nào làm cho phong trào ở Nghệ - Tĩnh lên cao?",["Vì Nghệ - Tĩnh đã lập được chính quyền xô viết.","Vì Nghệ - Tĩnh có tổ chức cộng sản và cơ sở đảng khá mạnh.","Vì nhân dân ở đây có lòng yêu nước và căm thù giặc sâu sắc.","Vì cơ sở công nghiệp Vinh - Bến Thủy ở Nghệ - Tĩnh là trung tâm kỹ nghệ lớn nhất ở Việt Nam."],"b",""],[204,"Sau thất bại của Chiến tranh đặc biệt, Mỹ chuyển sang loại hình chiến lược chiến tranh nào?",["Chiến tranh đơn phương.","Chiến tranh cục bộ.","Việt Nam hóa chiến tranh.","Đông Dương hóa chiến tranh."],"b",""],[205,"Ai được bầu làm Tổng Bí thư của Đảng tại Đại hội đại biểu lần thứ II (1951)?",["Trần Phú","Hồ Chí Minh","Trường Chinh","Lê Hồng Phong"],"c","(Kiểu hỏi khác: Đại hội lần thứ II của Đảng (1951) đã bầu ai làm Tổng Bí thư? A. Hồ Chí Minh B. Lê Duẩn C. Trường Chinh D. Phạm Văn Đồng)"],[206,"Đại hội lần thứ III (9-1960), Đảng Lao động Việt Nam khẳng định nhiệm vụ cách mạng giữ vai trò quyết định nhất đối với sự phát triển cách mạng cả nước là :",["Cách mạng xã hội chủ nghĩa ở miền Bắc","Cách mạng dân tộc dân chủ nhân dân ở miền Nam","Cách mạng hai miền đều quyết định như nhau","Các phương án trả lời đều sai"],"a",""],[207,"Qua thực tế lãnh đạo phong trào cách mạng 1930-1931, Đảng ta đã trưởng thành nhanh chóng. Do đó, tháng 4/1931 Đảng ta được Quốc tế Cộng sản công nhận:",["Là một chi bộ của Quốc tế Cộng sản","Là một bộ phận không thể tách rời của Quốc tế Cộng sản","Là một chính đảng của cách mạng Đông Dương","Là một Đảng của giai cấp công nhân Việt Nam"],"a",""],[208,"Một trong những bài học trong 10 năm đổi mới đất nước 1986-1996 là :",["Kinh tế thị trường nói chung và kinh tế thị trường định hướng XHCN khác nhau hoàn toàn","Kinh tế thị trường nói chung và kinh tế thị trường định hướng XHCN giống nhau về bản chất chỉ khác về hình thức","Kinh tế thị trường nói chung và kinh tế thị trường định hướng XHCN giống nhau hoàn toàn.","Xây dựng nền KT hàng hóa nhiều thành phần vận hành cơ chế thị trường, tăng cường quản lý Nhà nước theo định hướng XHCN. Tăng trưởng KT gắn tiến bộ công bằng XH, giữ và phát huy bản sắc văn hóa dân tộc, bảo vệ môi trường sinh thái."],"d",""],[209,"Vì sao trong những năm 1939-1941 Đảng Cộng sản Đông Dương lại phải chuyển hướng chiến lược đấu tranh cách mạng?",["Do sự biến đổi mau lẹ của tình hình thế giới","Do chính sách thống trị của Pháp - Nhật","Do yêu cầu của sự nghiệp giải phóng dân tộc đặt ra cấp thiết.","Do yêu cầu giải quyết vấn đề dân tộc trong khuôn khổ từng nước Đông Dương"],"c",""],[210,"Trong 10 năm đổi mới đất nước vấn đề tăng cường vai trò lãnh đạo của Đảng, coi xây dựng Đảng là :",["Nhiệm vụ then chốt","Nhiệm vụ quan trọng","Động lực phát triển","Gắn liền với phát triển kinh tế"],"a",""],[211,"Ta đã nhân nhượng với quân trung hoa dân quốc như thế nào?",["Chấp nhận mọi yêu cầu cải tổ Chính phủ, Quốc Hội theo ý chúng THDQ","Chấp nhận tiêu tiền TQ, Cung cấp một phần lương thực, thực phẩm cho quân Tưởng","Chấp nhận tất cả mọi yêu cầu đảm bảo trật tự trị an, phương tiện đi lại của quân Tưởng.","Chấp nhận cung cấp toàn bộ - lương thực thực phẩm cho quân Tưởng."],"b",""],[212,"Tại sao Đại hội V - 1982 lại nhận thức và coi nông nghiệp là mặt trận hảng đầu?",["Phù hợp với thời kỳ quá độ xây dựng xã hội chủ nghĩa.","Phù hợp với thời kỳ quá độ xây dựng xã hội chủ nghĩa, hội nhập quốc tế.","Nhận thức đó phù hợp với nước ta để khai thác thế mạnh, tiềm năng của đất nước về lao động, đất đai, ngành nghề v.v, tạo tiền đề cho những chặng đường tiếp theo.","Nhận thức đó phù hợp với nước ta để khai thác thế mạnh, tiềm năng của đất nước về lao động, đất đai, ngành nghề , động lực phát triển công nghiệp hóa-hiện đại hóa đất nước."],"c",""],[213,"Để kéo dài thời gian chuẩn bị lực lượng cho cuộc kháng chiến toàn quốc chống Pháp, sau Hiệp định Sơ bộ (6/3/1946), Chính phủ nước Việt Nam Dân chủ Cộng hòa tiếp tục kí với Pháp bản",["Hiệp định Giơnevơ.","Hòa ước.","Hiệp định Pari.","Tạm ước."],"d",""],[214,"Nhiệm vụ của cách mạng miền bắc ngay sau khi Hiệp định Giơ-ne-vơ năm 1954 về Đông Dương được kí kết là :",["Đấu tranh chống đế quốc Mĩ và chính quyền Ngô Đình Diệm","Xây dựng cơ sở vật chất kĩ thuật cho chủ nghĩa xã hội","Hoàn thành cuộc cách mạng dân tộc dân chủ nhân dân","Hàn gắn vết thương chiến tranh, khôi phục kinh tế"],"d",""],[215,"Sau cách mạng tháng Tám năm 1945, khó khăn lớn nhất đưa nước ta vào tình thế \"ngàn cân treo sợi tóc\" là gì?",["Khó khăn về thù trong, giặc ngoài","Nạn đói, nạn dốt đe doạ nghiêm trọng đến nhân dân ta","Ngân sách nhà nước trống rỗng","Hơn 90% dân số không biết chữ"],"a",""],[216,"Sau Cách mạng tháng Tám năm 1945, tàn dư văn hóa lạc hậu của chế độ thực dân, phong kiến để lại hết sức nặng nề là :",["Hơn 60% dân số không biết chữ","Hơn 70% dân số không biết chữ","Hơn 80% dân số không biết chữ","Hơn 90% dân số không biết chữ"],"d",""],[217,"Tình hình đất nước ta sau cách mạng tháng tám năm 1945 được ví như:",["Nước sôi, lửa bỏng","Nhẹ như lông hồng","Ngàn cân treo sợi tóc","Trứng, nước"],"c",""],[218,"Hội nghị Trung ương IV, khóa VIII tháng 12/1997 bầu ai làm Tổng bí thư của Đảng?",["Lê Khả Phiêu","Trường Chinh","Đỗ Mười","Nguyễn Văn Linh"],"a",""],[219,"Được ghi vào lịch sử dân tộc như một Bạch Đằng, một Chi Lăng, một Đống Đa thế kỉ XX. Đó là ý nghĩa của chiến thắng nào?",["Cách mạng tháng Tám 1945","Chiến dịch Điện Biên Phủ 1954","Chiến dịch Huế- Đà Nẵng 1975","Chiến dịch Hồ Chí Minh 1975"],"b",""],[220,"Sự kiện lịch sử nào ảnh hưởng đến phong trào cách mạng nước ta trong những năm 1930-1931?",["Cách mạng tháng Mười Nga thành công","Sự thành lập Quốc tế Cộng sản","Cuộc khủng hoảng kinh tế 1929-1933","Thắng lợi của cách mạng tháng Tám"],"c",""],[221,"Hội nghị Trung ương VIII khóa IX tháng 7/2003 đã ban hành:",["Thực hiện dân chủ xã hội chủ nghĩa","Kết hợp chặt chẽ ngay từ đầu đổi mới kinh tế với đổi mới chính trị","Đổi mới hệ thống chính trị một cách toàn diện, đồng bộ","Chiến lược bảo vệ Tổ quốc trong tình hình mới"],"d","(Hội nghị Trung ương 8 khóa 9 tháng 7/2003 đã ban hành: a. Chiến lược bảo vệ Tổ quốc trong tình hình mới b. Chiến lược phát triển giáo dục, y tế c. Chiến lược mở rộng xuất khẩu d. Chiến lược thu hút nguồn vốn)"],[222,"Hội nghị trung ương VIII tháng 5/1941 đề ra chủ trương gì?",["Thành lập nước Cộng hòa xã hội chủ nghĩa Việt Nam","Thành lập nước Việt Nam cộng hòa dân chủ","Thành lập nước dân chủ cộng hòa Việt Nam","Thành lập nước Việt Nam dân chủ cộng hòa"],"d",""],[223,"Tính chất của xã hội Việt Nam dưới sự thống trị của thực dân Pháp là :",["Xã hội thuộc địa, nửa phong kiến","Xã hội phong kiến","Xã hội thuôc địa","Xã hội chiếm hữu"],"a","(Kiểu hỏi khác: Tính chất của xã hội Việt Nam sau khi thực dân Pháp đặt được ách cai trị là gì? Chế độ cai trị của thực dân Pháp đối với nhân dân Việt Nam cuối thế kỷ XIX đầu thế kỷ XX là chế độ nào?)"],[224,"Mục tiêu cụ thể trước mắt của phong trào vận động dân chủ Đông Dương (1936-1939) là gì?",["Độc lập dân tộc, gắn với chủ nghĩa xã hội","Các quyền tự do, dân chủ, cơm áo và hòa bình","Ruộng đất cho dân cày","Đánh đổ đế quốc Pháp và tay sai"],"b",""],[225,"Mặt trận Việt Nam độc lập đồng minh được thành lập năm nào?",["19/5/1940","19/5/1941","19/5/1942","19/5/1943"],"b",""],[226,"Mặt trận dân chủ Đông dương chính thức thành lập vào năm nào?",["Năm 1938","Năm 1930","Năm 1941","Năm 1945"],"a",""],[227,"Để tuyên truyền chủ nghĩa Mác trong giai đoạn 1932-1933, Đảng Cộng sản Việt Nam đã sử dụng phương pháp gì?",["Tổ chức các hội công khai, như hội cấy, hội cày, hội đá bóng...","Tổ chức các cuộc bút chiến công khai","Tổ chức các buổi học bí mật","Tổ chức giải truyền đơn"],"b",""],[228,"Nội dung nào sai trong các bài học lãnh đạo cách mạng của Đảng để dẫn tới cách mạng Tháng Tám 1945 thắng lợi",["Giương cao ngọn cờ độc lập dân tộc, kết hợp đúng đắn hai nhiệm vụ chống đế quốc và chống phong kiến.","Sử dụng lực lượng vũ trang áp đảo tiêu diệt kẻ thù","Lợi dụng mâu thuẫn trong hàng ngũ kẻ thù.","Nắm vững nghệ thuật khởi nghĩa, nghệ thuật chọn đúng thời cơ."],"b",""],[229,"Bài học \"giương cao ngọn cờ độc lập dân tộc, kết hợp đúng đắn hai nhiệm vụ chống đế quốc và chống phong kiến\" được Đảng rút ra sau thời gian nào?",["Cách mạng Tháng Tám","Cách mạng dân tộc dân chủ nhân dân ở miền Nam","Cách mạng xã hội chủ nghĩa ở miền Bắc","Cách mạng Tháng Mười"],"a",""],[230,"Lần đầu tiên Ban Chấp hành Trung ương Đảng tại hội nghị lần thứ 8 (5-1941) chủ trương thành lập chính quyền Nhà nước với hình thức gì?",["Cộng hòa dân chủ","Cộng hòa xã hội chủ nghĩa","Cộng hòa nghị viện","Cộng hòa nhân dân"],"a",""],[231,"Chính phủ lâm thời nước Việt Nam dân chủ cộng hòa ra đời từ tổ chức nào?",["Việt Minh","Ủy ban dân tộc giải phóng Việt Nam","Ủy ban lâm thời khu giải phóng","Ủy ban khởi nghĩa"],"b",""],[232,"Chủ trương điều chỉnh chiến lược cách mạng của Đảng được bắt đầu từ Hội nghị Trung ương nào của khóa I?",["Hội nghị Trung ương 6 (11/1939)","Hội nghị Trung ương 7 (11/1940)","Hội nghị Trung ương 8 (5/1941)"],"a",""],[233,"Đảng chủ trương thành lập mặt trận Việt Minh vì mục đích gì?",["Nhằm tập hợp rộng rãi nông dân chống đế quốc","Tạm gác lại khẩu hiệu \"đánh đổ địa chủ, chia ruộng đất cho dân cày\"","Để đoàn kết, tập hợp lực lượng cách mạng nhằm giải phóng dân tộc","Nhằm tranh thủ lực lượng đồng minh chống phát xít Nhật"],"c",""],[234,"Phát xít Nhật xâm lược nước ta vào ngày tháng, năm nào?",["Ngày 22 Tháng 9-1940","Ngày 26 Tháng 9-1940","Ngày 20 Tháng 9-1940","Ngày 25 Tháng 9-1940"],"a",""],[235,"Hội Việt Nam Cách mạng Thanh niên hoạt động theo khuynh hướng nào?",["Khuynh hướng phong kiến","Khuynh hướng vô sản","Khuynh hướng tư sản","Khuynh hướng tiểu tư sản"],"b",""],[236,"Chỉ thị Kháng chiến kiến quốc của Trung ương Đảng ngày 25/11/1945, xác định nhiệm vụ nào là trung tâm, bao trùm nhất?",["Củng cố, bảo vệ chính quyền cách mạng","Chống thực dân Pháp xâm lược","Cải thiện đời sống nhân dân","Củng cố, bảo vệ chính quyền cách mạng"],"d",""],[237,"Lực lượng tạo nên động lực cho cách mạng Việt Nam được nêu ra trong Chính cương của Đảng Lao động Việt Nam là:",["Công nhân, nông dân, tiểu tư sản, tư sản dân tộc, địa chủ yêu nước","Công nhân, nông dân, lao động trí thức","Công nhân, trí thức, tư sản dân tộc","Địa chủ, tư sản dân tộc","Công nhân, nông dân, tiểu tư sản, tư sản dân tộc, đại địa chủ"],"a",""],[238,"Sự kiện nào được Nguyễn Ái Quốc đánh giá \"Nó là quả trứng, mà từ đó nở ra con chim non Cộng sản\"?",["Cách mạng tháng Mười Nga bùng nổ và thắng lợi","Sự thành lập Đảng cộng sản Pháp","Vụ mưu sát tên toàn quyền Méc lanh (Pháp) của Phạm Hồng Thái","Sự thành lập Hội Việt Nam cách mạng thanh niên"],"d",""],[239,"Hội nghị Ban Chấp hành Trung ương Đảng Cộng sản Việt Nam (10-1930) đã đổi tên đảng thành :",["Đông Dương Cộng sản Đảng","Đảng Lao động Việt Nam","Đảng Cộng sản Đông Dương","Đảng An Nam"],"c",""],[240,"Một trong những tổ chức Cộng sản ra đời ở Việt Nam năm 1929 là:",["Hội Việt Nam cách mạng Thanh Niên","Việt Nam Quốc dân đảng","Tân Việt Cách mạng đảng","Đông Dương Cộng sản đảng"],"d","(Kiểu hỏi khác: Tổ chức cộng sản ra đời đầu tiên ở Việt Nam là tổ chức nào?)"],[241,"Thành phần nào dưới đây trở thành bị trị trong thời Pháp thuộc?",["Công nhân và nông dân","Công nhân, nông dân, tiểu tư sản","Công nhân, nông dân, tiểu tư sản, tư sản dân tộc","Công nhân, nông dân, tiểu tư sản, tư sản dân tộc, địa chủ nhỏ và vừa"],"d",""],[242,"Đảng Cộng sản Việt Nam ra đời là :",["Tất yếu lịch sử, nó là sản phẩm kết hợp giữa chủ nghĩa Mác với phong trào công nhân Việt Nam.","Sản phẩm kết hợp giữa chủ nghĩa Mác với phong trào yêu nước Việt Nam.","Sản phẩm của sự kết hợp chủ nghĩa Mác-Lênin với phong trào công nhân và phong trào yêu nước","Sự kết hợp phong trào công nhân và phong trào yêu nước Việt Nam."],"c",""],[243,"Vào tháng 10/1923, Nguyễn Ái Quốc đến Liên Xô tham dự đại hội của :",["Quốc tế Vô sản","Quốc tế Nông dân","Liên hiệp các nước thuộc địa"],"b",""],[244,"Nguyễn Ái Quốc đã thành lập Hội Việt Nam cách mạng thanh niên ở đâu?",["Hương Cảng (Trung Quốc)","Quảng Châu (Trung Quốc)","Thượng Hải (Trung Quốc)","Cao Bằng (Việt Nam)"],"b",""],[245,"Nguyễn Ái Quốc đọc \"Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa\" của Lênin vào thời gian nào?",["7/1917","7/1918","7/1919","7/1920"],"d","(Kiểu hỏi khác: Hồ Chí Minh đọc bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin trên báo nào? -> Nhân Đạo)"],[246,"Sự kiện tháng 6-1924 gắn với hoạt động của Nguyễn Ái Quốc ở Liên Xô, đó là:",["Người dự Đại hội Quốc tế Nông dân.","Người dự Đại hội lần thứ V của Quốc tế Cộng sản.","Người dự Đại hội Quốc tế Phụ nữ.","Người dự Đại hội lần thứ VII của Quốc tế Cộng sản."],"b",""],[247,"Hoạt động của Phan Bội Châu, Phan Châu Trinh và một số người sống ở nước ngoài có tác dụng quan trọng nhất là:",["Mở mang dân trí.","Tìm được con đường cứu nước cho dân tộc.","Góp phần cải thiện đời sống của nhân dân.","Cổ vũ, thức tỉnh lòng yêu nước của nhân dân ta."],"d",""],[248,"Lực lượng chính của cách mạng được xác định trong Luận cương chính trị (10-1930) là :",["Công nhân và nông dân","Toàn thể nhân dân","Nông dân và tiểu tư sản","Nông dân và tư sản dân tộc"],"a",""],[249,"Nội dung nào sau đây nằm trong Cương lĩnh cách mạng đầu tiên của Đảng?",["Đánh đổ đế quốc chủ nghĩa Pháp và bọn phong kiến, làm cho nước Nam hoàn toàn độc lập","Tư sản dân quyền cách mạng là thời kỳ dự bị để làm xã hội cách mạng","Chỉ có giải phóng giai cấp vô sản mới giải phóng được dân tộc","Đảng có vững cách mạng mới thành công"],"a","(Kiểu hỏi khác: Nội dung nào sau đây nắm trong Cương lỉnh chính trị đầu tiên của Đảng?)"],[250,"Hạn chế lớn nhất của Luận cương chính trị tháng 10 năm 1930 là gì?",["Đánh giá không đúng khả năng cách mạng của giai cấp nông dân","Không đưa ngọn cờ giải phóng dân tộc lên hàng đầu, nặng về đấu tranh giai cấp","Xác định động lực cách mạng là giai cấp công nhân, nông dân, tiểu tư sản trí thức","Cách mạng Đông Dương lúc đầu là cách mạng tư sản dân quyền bỏ qua thời kì tư"],"b",""],[251,"Hội nghị Ban chấp hành Trung ương Đảng Cộng sản Đông Dương (7-1936) đã chủ trương thành lập :",["Mặt trận thống nhất dân chủ Đông Dương","Mặt trận Việt Nam độc lập Đồng minh","Mặt trận thống nhất dân tộc phản đế Đông Dương","Mặt trận thống nhất nhân dân phản đế Đông Dương"],"d",""],[252,"Nhiệm vụ cách mạng được cương lĩnh xác định là :",["Đánh đổ phong kiến, đánh đổ đế quốc, 2 nhiệm vụ có quan hệ mật thiết khăng khít với nhau.","Đánh đổ đế quốc Pháp và tư sản phản cách mạng","Đánh đổ đế quốc Pháp, phong kiến, tư sản phản cách mạng làm cho nước nhà độc lập.","Đánh đuổi đế quốc Pháp"],"c",""],[253,"Sự kiện nào dưới đây đánh dấu khuynh hướng cách mạng vô sản giành quyền lãnh đạo đối với cách mạng Việt Nam ?",["Hội Việt Nam Cách mạng thanh niên ra đời","Tân Việt Cách mạng đảng bị phân hoá.","Sự ra đời của ba tổ chức cộng sản","Đảng Cộng sản Việt Nam được thành lập."],"d",""],[254,"Sự khác biệt cơ bản giữa phong trào đấu tranh của nhân dân Việt Nam từ năm 1939 đến trước ngày 9-3-1945 với các phong trào cách mạng trước đó là gì?",["Chống lại nền thống trị của đế quốc phát xít Pháp - Nhật","Nhiệm vụ giải phóng dân tộc đặt ra cấp thiết","Mâu thuẫn dân tộc phát triển gay gắt","Có sự liên kết với quốc tế"],"b",""],[255,"Nhiệm vụ của cách mạng Việt Nam được xác định trong Cương lĩnh chính trị đầu tiên của Đảng là gì?",["Đánh đổ đế quốc Pháp, làm cho nước Việt Nam hoàn toàn độc lập","Đánh đổ phong kiến, tay sai, phát triển theo con đường tư ban̉ chủ nghĩa","Đánh đổ đế quốc Pháp, phong kiến và tư sản phản cách mạng làm cho Việt Nam được độc lập tự do","Đánh đổ để quốc Pháp, phong kiến làm cho Việt Nam hoàn toàn độc lập"],"c",""],[256,"So với trước chiến tranh thế giới thứ nhất, phong trào yêu nước Việt Nam trong những năm 1919-1930 có những điểm mới nào sau đây?",["Có hai khuynh hướng cùng tồn tại và phát triển","Diễn ra dưới tác động của cuộc khai thác thuộc địa của thực dân Pháp","Giai cấp công nhân nắm lấy vai trò lãnh đạo cách mạng giải phóng dân tộc","Cách mạng Việt Nam nhận được sự ủng hộ, giúp đỡ của Liên Xô, Trung Quốc"],"a",""],[257,"Điểm khác biệt và độc đáo nhất của Nguyễn Ái Quốc trong hành trình tìm đường cứu nước so các tiền bối khác ?",["Hướng đi và cách tiếp cận chân lý.","Từ yêu nước đến chủ nghĩa Mác -Lê nin.","Gắn độc lập dân tộc với vấn đề ruộng đất","Dự đoán chính xác thời cơ cách mạng."],"a","(Nếu chọn 2 thì chọn AB)"],[258,"Để thực hiện chính sách \"Tố cộng, diệt cộng\" Ngô Định Diệm đưa ra :",["Luật 10/59","Luật nhân quyền","Luật bình định","Các phương án trả lời đều đúng"],"a",""],[259,"Đại hội II của Đảng Lao động Việt Nam vạch ra tính chất của xã hội Việt Nam là:",["Dân chủ nhân dân, một phần thuộc địa và nửa phong kiến","Dân chủ nhân dân, thuộc địa và nửa phong kiến","Dân chủ nhân dân và nửa phong kiến","Một phần thuộc địa và nửa phong kiến"],"a",""],[260,"Bản chỉ thị \"Kháng chiến, kiến quốc\" ngày 25/11/1945 của Trung ương Đảng đã xác định ai là kẻ thù chính của cách mạng Việt Nam lúc này?",["Thực dân Pháp","Đế quốc Anh","Bọn quân phiệt quốc dân đảng Trung Hoa","Phát xít Nhật"],"a","(Kiểu hỏi khác: Chi thị Kháng chiến kiến quốc (25/11/1945) xác định kẻ thù chính của cách mạng Việt Nam lúc bấy giờ là)"],[261,"Đầu năm 1953, nhằm cứu vãn tình thế ngày càng xa lầy và tìm kiếm giải pháp chính trị có \"danh dự\", Pháp và Mỹ đã đưa một viên tướng Pháp sang làm tổng chỉ huy quân đội pháp ở Đông Dương và lập kế hoạch quân sự nào?",["Nava","De Castries","Salan","Leclerc"],"a",""],[262,"Trong cương lĩnh thứ ba - Chính cương của Đảng Lao động Việt Nam (2/1951), Đảng ta đã khẳng định nhận thức của mình về triển vọng của cách mạng Việt Nam là:",["Đi tới xã hội cộng sản","Tiến tới chủ nghĩa xã hội","Đi tới xã hội dân chủ","Tiến tới chủ nghĩa tư bản"],"b",""],[263,"Nghị quyết về đường lối cách mạng miền Nam được thông qua tại Đại hội nào của Đảng sau đây?",["Đại hội II","Đại hội III","Đại hội IV","Đại hội I"],"b",""],[264,"Khối liên minh nhân dân ba nước Việt-Lào-Campuchia được thành lập khi nào?",["Tháng 3 năm 1950","Tháng 3 năm 1953","Tháng 3 năm 1954","Tháng 3 năm 1951"],"d",""],[265,"Ngay sau khi cách mạng Tháng Tám 1945 thành công, Thực dân Pháp được Đảng coi là kẻ thù như thế nào?",["Kẻ thù chính","Kẻ thù phụ","Không nguy hiểm","Chờ giải giáp của quân đồng minh"],"a","(Kiểu hỏi khác: Sau cách mạng Tháng 8 năm 1945 thành công, Đảng Cộng sản Đông Dương xác định thực dân Pháp là kẻ thù như nào?"],[266,"Nội dung nào dưới đây thuộc Hiệp định Sơ bộ (6 - 3 - 1946)?",["Việt Nam là một quốc gia độc lập trong khối Liên hợp Pháp.","Việt Nam là một quốc gia tự trị trong khối Liên hợp Pháp.","Việt Nam là một quốc gia tự do trong khối Liên hợp Pháp.","Việt Nam là một quốc gia tự chủ trong khối Liên hợp Pháp."],"c",""],[267,"Đường lối kháng chiến chống thực dân Pháp xâm lược của Đảng (1946-1954) là:",["Toàn dân, toàn diện, lâu dài và tự lực cánh sinh","Toàn diện, lâu dài và tự lực cánh sinh","Chiến tranh nhân dân, toàn diện và tự lực cánh sinh","Chiến tranh nhân dân, toàn diện, lâu dài và tranh thủ ngoại lực"],"a",""],[268,"Đường lối kháng chiến \"Dựa vào sức mình là chính\" được Đảng xác định là :",["\"Phải tự cấp, tự túc về mọi mặt\"","\"Phải đánh địch bằng sức mình\"","\"Phải tự vũ trang để thắng định về mọi mặt\"","\"Phải biết tranh thủ sự giúp đỡ của các nước\""],"a",""],[269,"Từ tháng 9-1945 đến tháng 3-1946 ta chủ trương :",["Hòa với Tưởng","Hòa với Pháp","Đánh Tưởng","Đánh Pháp"],"a",""],[270,"Căn cứ địa cách mạng của ta trong cuộc kháng chiến chống Pháp xâm lược lần thứ hai là :",["Hà Nội","Biên Giới","Việt Bắc","Điện Biên Phủ"],"c",""],[271,"Tác phẩm \"Kháng chiến nhất định thắng lợi\" là của ai?",["Trường Chinh","Võ Nguyên Giáp","Hồ Chí Minh","Trần Phú"],"a",""],[272,"Kế hoạch quân sự được xem là lớn nhất trong quá trình xâm lược Việt Nam của Pháp từ 1945-1954?",["Kế hoạch Rơve","Kế hoạch Nava","Kế hoạch \"đánh nhanh thắng nhanh\"","Kế hoạch Đờ Lát đơ Tátxinhi"],"b",""],[273,"Chiến dịch Điện Biên Phủ được coi là một chiến dịch lịch sử của quân đội ta và được chia làm bao nhiêu đợt?",["2 đợt","3 đợt","4 đợt","5 đợt"],"b",""],[274,"Thắng lợi nào của quân và dân ta trong cuộc kháng chiến chống Pháp đã làm phá sản hoàn toàn kế hoạch Nava?",["Chiến thắng Biên giới Thu - Đông 1950","Chiến thắng Tây Bắc 1953","Chiến thắng Điện Biên Phủ 1954","Chiến thắng Thượng Lào 1954"],"c",""],[275,"Thắng lợi ngoại giao lớn nhất của ta trong cuộc kháng chiến chống Pháp từ 1945-1954 là :",["Hiệp định Sơ bộ 1946","Tạm ước 1946","Hiệp định Giơnevơ 1954","Liên Xô, Trung Quốc đặt quan hệ ngoại giao với ta 1950"],"c",""],[276,"Chiến thắng Điện Biên Phủ năm 1954 của quân dân Việt Nam đã:",["Đánh dấu mốc thắng lợi của cuộc kháng chiến chống Pháp","Làm phá sản hoàn toàn kế hoạch Nava của thực dân Pháp.","Buộc Pháp phải ngồi vào đàm phán tại Giơnevơ.","Bước đầu làm phá sản kế hoạch Nava của thực dân Pháp."],"b","(Nếu đề bảo chọn 3 thì chọn ABC)"],[277,"Một trong những khó khăn của nước ta trong những năm 1953-1954 là :",["Chủ nghĩa đế quốc xâm lược và phong kiến","Bọn can thiệp Mỹ và phong kiến phản động","Đế quốc Pháp và phong kiến","Đế quốc Pháp và bọn can thiệp Mỹ"],"d",""],[278,"Mặt trận Dân tộc giải phóng miền Nam Việt Nam được thành lập do ai làm chủ tịch?",["Nguyễn Hữu Thọ","Nguyễn Thị Định","Võ Nguyên Giáp","Trường Chinh"],"a",""],[279,"Nhận xét nào là phù hợp khi nói về mối quan hệ của hai miền đất nước trong cuộc kháng chiến chống Mỹ?",["Cách mạng hai miền có mối quan hệ mật thiết với nhau và có tác dụng thúc đẩy lẫn nhau","Cách mạng hai miền có quan hệ quyết định lẫn nhau","Cách mạng hai miền có quan hệ mật thiết với nhau","Cách mạng hai miền có quan hệ độc lập với nhau và có tác dụng thúc đẩy lẫn nhau"],"a",""],[280,"Ở Việt Nam, cuộc kháng chiến chống Mĩ, cứu nước (1954-1975) có điểm mới nào sau đây so với cuộc kháng chiến chống thực dân Pháp (1945-1954)?",["Hoàn thành đồng thời nhiệm vụ kháng chiến và gây dựng cơ sở cho chế độ mới.","Thực hiện tư tưởng tiến công bằng sức mạnh của lực lượng vũ trang ba thứ quân.","Kết hợp khởi nghĩa từng phần của quần chúng nhân dân với chiến tranh cách mạng."],"c",""],[281,"Cơ chế thị trường trong nền kinh tế Việt Nam từ 1986- 1991 được xem là:",["Chưa đầy đủ","Đầy đủ","Hoàn hảo","Hoàn thiện"],"a",""],[282,"Một trong những nhận thức mới của Đảng về chủ nghĩa xã hội là :",["Phát tiển các doanh nghiệp nhà nước","Các tài sản thuộc sở hữu toàn dân","Các quỹ dự trữ quốc gia, quỹ bảo hiểm nhà nước","Xây dựng con người mới XHCN"],"d",""],[283,"Mục tiêu xây dựng chủ nghĩa xã hội ở Việt Nam là:",["Mở rộng quan hệ hợp tác với các nước trên thế giới","Kinh tế tư bản nhà nước","Kinh tế có vốn đầu tư nước ngoài theo định hướng xã hội chủ nghĩa","Dân giàu, nước mạnh, xã hội công bằng, văn minh"],"d",""],[284,"Trọng tâm của đổi mới kinh tế tại Đại hội VI (1986) là :",["Đổi mới cơ chế quản lý, xóa bỏ cơ chế tập trung quan liêu hành chính, bao cấp.","Đổi mới tổ chức và phương thức hoạt động của nhà nước","Đổi mới tổ chức và phương thức hoạt động của các tổ chức tư nhân","Đổi mới tổ chức và phương thức hoạt động của Mặt trận tổ quốc Việt Nam"],"a",""],[285,"Ba chương trình kinh tế lớn của ta sau đổi mới kinh tế là:",["Lương thực - thực phẩm, hàng tiêu dùng và hàng xuất khẩu","Lương thực - thực phẩm, hàng tiêu dùng","Nông-công nghiệp, dịch vụ","Công nghiệp, thương nghiệp, dịch vụ"],"a",""],[286,"Từ ngày 15 - 21/11/1975, Hội nghị Hiệp thương chính trị của 2 đoàn đại biểu miền Bắc - Nam đã họp tại:",["Sài Gòn","Huế","Đà Nẵng","Hà Nội"],"a",""],[287,"Trong quá trình đổi mới mới đất nước, Đảng cộng sản Việt Nam đóng vai trò là:",["Không tham gia trong hệ thống chính trị","Đóng vai trò trụ cột","Thực hiện vai trò một cách hạn chế trong hệ thống chính trị","Đóng vai trò thứ yếu"],"b",""],[288,"Năm 2012 có bao nhiêu nước công nhận cơ chế kinh tế thị trường của Việt Nam?",["36 nước","38 nước","40 nước","44 nước"],"a",""],[289,"Đại hội đại biểu toàn quốc lần thứ XIII Đảng Cộng sản Việt Nam họp từ ngày nào?",["từ ngày 23.1-1.2.2021","từ ngày 25.1-1.2.2021","từ ngày 26.1-1.2.2021","từ ngày 24.1-1.2.2021"],"b",""],[290,"Bộ Chính trị ban hành Chỉ thị số 5-CT/TW ngày 15/5/2016 về:",["Thống nhất nhận thức về kinh tế thị trường định hướng XHCN.","Hoàn thiện thể chế về sở hữu và các thành phần kinh tế.","Học tập và làm theo tư tưởng Hồ Chí Minh.","Đẩy mạnh học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh."],"d",""],[291,"Mở rộng các lĩnh vực kinh tế thuộc độc quyền nhà nước là vi phạm nguyên tắc",["Hoàn thiện thể chế gắn tăng trưởng kinh tế với tiến bộ, công bằng xã hội và bảo vệ môi trường.","Hoàn thiện thể chế về sở hữu và các thành phần kinh tế.","Hoàn thiện thể chế đảm bảo đồng bộ các yếu tố thị trường và phát triển đồng bộ các loại thị trường."],"b",""],[292,"Hội nghị Trung ương V khóa XII, tháng 5/2017 chủ trương:",["Chủ trương phát triển kinh tế thị trường định hướng XHCN","Chủ trương phát triển kinh tế thị trường tư bản chủ nghĩa","Chủ trương phát triển kinh tế chỉ huy","Hoàn thiện thể chế kinh tế thị trường định hướng xã hội chủ nghĩa."],"d",""],[293,"Trong 5 yếu tố chính để tăng trưởng kinh tế, yếu tố nào giữ vai trò quyết định?",["Vốn, Khoa học- công nghệ","Con người","Cơ cấu kinh tế","Thể chế chính trị và quản lý nhà nước"],"b",""],[294,"Hội nghị Trung ương 7 khóa 12 đã ban hành Nghị quyết số 27-NQ/TW ngày 21/5/2018 về:",["Cải cách chính sách tiền lương đối với cán bộ, công viên chức, lực lượng vũ trang và người lao động trong doanh nghiệp.","Xây dựng văn hóa trong tình hình mới","Hội nhập trong tình hình mới","Tăng cường công tác bảo vệ, chăm sóc và nâng cao sức khỏe nhân dân trong tình hình mới."],"a",""],[295,"Hội nghị trung ương VI khoá VI (tháng 3 năm 1989) lần đầu tiên đưa ra thuật ngữ gì?",["Kinh tế thị trường định hướng xã hội chủ nghĩa","Hệ thống chính trị","Nhà nước pháp quyền xã hội chủ nghĩa","Đảng lãnh đạo, nhà nước quản lý, nhân dân làm chủ"],"b",""],[296,"Đại hội XIII đã đề ra mấy đột phá chiến lược để phát triển đất nước?",["3 đột phá","4 đột phá","5 đột phá","6 đột phá"],"a",""],[297,"Mọi công việc của Đảng, Nhà nước phải quán triệt sâu sắc lấy dân làm gốc, dân làm trung tâm, kiên trì thực hiện phương châm:",["Dân biết, dân bàn, dân làm, dân kiểm tra, dân giám sát, dân thụ hưởng","Dân biết, dân bàn, dân làm, dân kiểm tra, dân giám sát","Dân biết, dân bàn, dân làm, dân kiểm tra","Của dân, do dân và vì dân"],"a",""],[298,"Nội dung nào của Nghị quyết Trung ương 3, tháng 6/1997 về phát huy quyền ?",["Làm chủ của nhân dân","Lãnh đạo của Đảng","Của các tổ chức chính trị-xã hội","Của Mặt trận tổ quốc"],"a",""],[299,"Hội nghị Trung ương V khóa IX tháng 3/2002 đã thống nhất nhận thức về sự cần thiết phát triển kinh tế tập thể và thảo luận, thống nhất nhận thức coi:",["Kinh tế tư nhân đã phát triển rộng khắp trong cả nước, đóng góp quan trọng vào phát triển kinh tế","Kinh tế nhà nước đã phát triển rộng khắp trong cả nước, đóng góp quan trọng vào phát triển kinh tế","Sự lãnh đạo của Đảng quyết định sự phát triển kinh tế đất nước","Chủ nghĩa Mác Lênin, tư tưởng Hồ Chí Minh ngày càng giữ vai trò chủ đạo"],"a",""],[300,"Đại hội VIII đưa ra luận điểm quan trọng về công nghiệp hóa là",["Giai đoạn chuẩn bị các tiền đề công nghiệp hóa đất nước đã cơ bản hoàn thành, cho phép ta chuyển sang giai đọan đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước.","Công nghiệp hóa được nhận thức là \"công nghiệp hóa - hiện đại hóa\".","Công nghiệp hóa được nhận thức là \"công nghiệp hóa- hiện đại hóa gắnvới phát triển kinh tế tri thức\".","Công nghiệp hóa được nhận thức là \"công nghiệp hóa- hiện đại hóa gắnvới phát triển kinh tế tri thức trong cơ chế thị trường định hướng XHCN vàhội nhập kinh tế quốc tế\"."],"a",""],[301,"Việt Nam và Trung Quốc bình thường hóa quan hệ vào thời gian nào?",["11-1-2007","13-7-2001","10-11-1991","12-7-1995"],"c",""],[302,"Một trong những nhiệm vụ trọng tâm trong nhiệm kỳ đại hội đã được Đại hội Đảng lần thứ XIII nêu ra là :",["Tiếp tục đẩy mạnh xây dựng, chỉnh đốn Đảng, xây dựng Nhà nước pháp quyền xã hội chủ nghĩa và hệ thống chính trị toàn diện, trong sạch, vững mạnh. Đổi mới phương thức lãnh đạo, cầm quyền của Đảng","Ưu tiên phát triển công nghiệp công nghệ trung bình, công nghiệp chế tác, công nghiệp phần mềm và công nghiệp bổ trợ có lợi thế cạnh tranh","Tập trung phát triển công nghiệp nặng, công nghiệp chế tác, công nghiệp phần mềm và công nghiệp bổ trợ có lợi thế cạnh tranh"],"a",""],[303,"Tại sao cần cải cách chính sách tiền lương, bảo hiểm xã hội và trợ cấp ưu đãi người có công giai đoạn 2008 -2012:",["Việc trả lương đúng cho người lao động là thực hiện đầu tư cho phát triển, tạo động lực cho phát triển kính tế - xã hội","Việc trả lương đúng cho người lao đông sẽ khuyến khích người giỏi hăng say lao động và có đông lực phát triển đất nước","Việc trả lương đúng cho người lao động là thực hiện đấu tư cho phát triển, tạo động lực cho phát trển kinh tế xã hỏi, góp phần làm trong sạch và nâng cao hiệu lực, hiệu quả hoạt động của bộ máy nhà nước."],"c",""],[304,"Đảng đánh giá như thế nào về bộ phận công chức nhà nước hiện nay?",["Tình trạng quan liêu, hách dịch, nhũng nhiễu của một bộ phận công chức chưa được khắc phục","Tình trạng quan liêu, hách dịch, nhũng nhiễu của tất cả công chức còn phổ biến.","Tình trạng quan liêu, hách dịch, nhũng nhiễu của một bộ phận công chức đã được khắc phục.","Tình trạng quan liêu, hách dịch, nhũng nhiễu của tất cả công chức chưa được khắc phục."],"a",""],[305,"Nhận xét nào là đúng về hạn chế của nước ta sau 10 năm đổi mới 1986-1996?",["Việt Nam vẫn là nước nghèo, kém phát triển, xã hội còn nhiều tiêu cực và nhiều vấn đề phải giải quyết.","Việt Nam vẫn là nước nghèo, kém phát triển, xã hội còn nhiều tiêu cực","Việt Nam vẫn là nước nghèo, phát triển còn mất cân đối","Việt Nam vẫn là nước nghèo nàn, lạc hậu"],"a",""],[306,"Tháng 6-1925 gắn với sự ra đời của tổ chức nào?",["Hội Việt Nam cách mạng thanh niên","Đông Dương Cộng sản Đảng","Quốc dân Đảng","Đảng cộng sản Việt Nam"],"a",""],[307,"Hội nghị thành lập Đảng Cộng sản Việt Nam được tổ chức ở đâu?",["Hà Nội","Chiêm Hóa (Tuyên Quang)","Cửu Long- Hương Cảng-Trung Quốc","Quảng Châu- Trung Quốc"],"c",""],[308,"Tính chất toàn diện trong cuộc kháng chiến chống Pháp được hiểu là:",["Kháng chiến trên mọi lĩnh vực kinh tế, quân sự, chính trị, văn hóa, giáo dục","Tất cả mọi người dân đều tham gia kháng chiến","Kháng chiến lâu dài","Phải dựa vào sức mình"],"a",""],[309,"Chủ trương, nhận định nào là hạn chế của Đảng tại Đại hội lần thứ IV (1976)?",["Hoàn thành về cơ bản quá trình đưa nền kinh tế nước ta từ sản xuất nhỏ lên sản xuất lớn xã hội chủ nghĩa trong khoảng 20 năm","Quá độ lên chủ nghĩa xã hội ở nước ta là thời kỳ khó khăn, phức tạp, lâu dài, phải trải qua nhiều chặng đường","Nước ta đã thống nhất, cả nước tiến lên chủ nghĩa xã hội","Nước ta đang ở trong quá trình từ một xã hội có nền kinh tế sản xuất nhỏ tiến thẳng lên chủ nghĩa xã hội"],"a",""],[310,"Đường lối Đổi mới được Đảng đề ra tại Đại hội VI (1986) nhằm:",["Thay đổi mục tiêu xã hội chủ nghĩa","Làm cho mục tiêu xã hội chủ nghĩa được thực hiện tốt hơn","Từ bỏ những nguyên lý của chủ nghĩa Mác - Lênin","Thực hiện đa nguyên chính trị, đa đảng đối lập"],"b",""],[311,"Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội được Đại hội Đảng lần thứ VII (1991) thông qua xác định xã hội xã hội chủ nghĩa mà nhân dân ta xây dựng có mấy đặc trưng cơ bản?",["4","5","6","7"],"c",""],[312,"Tổng kết thành tựu 35 năm lãnh đạo công cuộc Đổi mới, Đại hội XIII của Đảng (1/2021) khẳng định.",["Đất nước ta chưa bao giờ giàu mạnh như ngày nay","Đất nước ta đã cơ bản hoàn thành sự nghiệp công nghiệp hóa, hiện đại hóa","Đất nước ta chưa bao giờ có được cơ đồ, tiềm lực, vị thế và uy tín quốc tế như ngày nay","Đất nước ta đã trở thành một nước công nghiệp hiện đại, theo định hướng xã hội chủ nghĩa"],"c",""],[313,"Chiến thắng Phước Long (1/1975) có ý nghĩa như thế nào đối với việc Đảng đề ra quyết tâm chiến lược giải phóng miền Nam trong hai năm 1975 - 1976?",["Đòn đánh quan trọng","Đòn đánh quyết định","Đòn thăm dò chiến lược","Đòn đánh mở màn"],"c",""],[314,"Xu hướng giành độc lập dân tộc theo con đường cải cách đất nước gắn với tên tuổi của nhà yêu nước nào?",["Phan Châu Trinh","Phan Bội Châu","Phan Đình Phùng","Phan Văn Trường"],"a",""],[315,"Hội nghị Trung ương II, khóa VIII tháng 12/1996 nhận định phát triển khoa học và công nghệ là",["Ưu tiên phát triển hàng đầu trong quá trình công nghiệp hóa - hiện đại hóa đất nước","Quan trọng nhất trong quá trình đổi mới đất nước","Ưu tiên phát triển hàng đầu trong quá trình hội nhập","Nhân tố quyết định tăng trưởng kinh tế xã hội"],"d",""],[316,"Nét nổi bật nhất về tình hình chính trị ở Việt Nam sau khi Hiệp định Giơnevơ về Đông Dương được ký kết là",["Hà Nội được giải phóng","Pháp rút quân khỏi Miền Bắc","Đất nước bị chia cắt thành hai miền với hai chế độ chính trị - xã hội khác nhau","Nhân dân hai miền tiến hành tổ chức hiệp thương tổng tuyển cử thống nhất đất nước"],"c",""],[317,"Hội nghị Trung ương VII khóa XII đã ban hành Nghị quyết số 28 - NQ/TW ngày 23/5/2018 về",["Đổi mới mục tiêu, con đường đi lên xã hội chủ nghĩa","Đổi mới nội dung, phương thức hoạt động, tổ chức cán bộ và quan hệ giữa các tổ chức trong hệ thống chính trị","Tăng cường công tác bảo vệ, chăm sóc và nâng cao sức khỏe nhân dân trong tình hình mới","Cải cách chính sách bảo hiểm xã hội"],"d",""],[318,"Đặc điểm lớn nhất của cách mạng Việt Nam sau tháng 7/1954 là",["Kẻ thủ chính lúc này là đế quốc Mỹ với tiềm lực kinh tế và quân sự hùng mạnh","Miền Bắc đi lên chủ nghĩa xã hội từ một nền nông nghiệp lạc hậu","Miền Nam trở thành thuộc địa kiểu mới, do chính quyền đối phương quản lý","Đất nước bị chia thành hai miền, có hai chế độ chính trị xã hội khác nhau"],"d",""],[319,"Một trong những bài học kinh nghiệm được rút ra trong 10 năm đổi mới đất nước (1986-1996) là",["Đổi mới tổ chức và phương thức hoạt động của hệ thống chính trị là nhằm thay đổi cách lãnh đạo của Đảng, hiệu lực quản lý của nhà nước, phát huy quyền làm chủ của nhân dân","Đổi mới tổ chức và phương thức hoạt động của hệ thống chính trị là nhằm tăng cường vai trò lãnh đạo của Đảng, hiệu lực quản lý của nhà nước, phát huy quyền làm chủ của nhân dân","Kết hợp chặt chẽ đổi mới kinh tế với đối mới chính trị, lấy đổi mới kinh tế làm trọng tâm, từng bước đổi mới chính trị","Đổi mới tổ chức và phương thức hoạt động của hệ thống chính trị là nhằm giảm bớt vai trò lãnh đạo của"],"c",""],[320,"Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (bổ sung, phát triển năm 2011) đặt ra mục tiêu xây dựng nước ta trở thành một nước công nghiệp hiện đại, theo định hướng xã hội chủ nghĩa vào năm:",["2020","2030","Giữa thế kỷ XXI","Cuối thế kỷ XXI"],"c",""],[321,"Xây dựng, chinh đốn Đảng được Đại hội X (2006) xác định là:",["Nhiệm vụ trung tâm","Nhiệm vụ then chốt","Nhiệm vụ hàng đầu","Nhiệm vụ đặc biệt quan trọng"],"b",""],[322,"Lãnh tụ Nguyễn Ái Quốc thành lập Hội Việt Nam Cách mạng Thanh niên (1925) là sự chuẩn bị cho sự ra đời của Đảng Cộng sản Việt Nam về mặt",["Tổ chức","Tư tưởng","Chính trị","Đường lối chính sách"],"a",""],[323,"Lãnh tụ Nguyễn Ái Quốc tìm thấy ở chủ nghĩa Lênin con đường giải phóng cho dân tộc Việt Nam thông qua việc:",["Gửi Bản yêu sách của nhân dân An Nam (1919)","Bỏ phiếu tán thành Quốc tế Cộng sản, sáng lập Đảng Cộng sản Pháp (1920)","Đọc Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa (1920)","Dự Đại hội lần thứ V Quốc tế Cộng sản (1924)"],"c",""],[324,"Nội dung Cương lĩnh chính trị đầu tiên (2/1930) của Đảng thể hiện trong:",["2 văn kiện","3 văn kiện","4 văn kiện","5 văn kiện"],"a",""],[325,"Ngày 19/10/1946, Ban Thường vụ Trung ương Đảng mở Hội nghị quân sự toàn quốc lần thứ nhất, do Tổng Bí thư Trường Chinh chủ trì, Hội nghị xác định",["\"Không sớm thì muộn, Pháp sẽ đánh mình và mình nhất định phải đánh Pháp\"","\"Không sớm thì muộn, Pháp sẽ hàng mình và mình nhất định phải đánh Pháp\"","\"Không sớm thì muộn, Pháp sẽ đàm phán với mình và mình nhất định sẽ thắng Pháp\""],"a",""],[326,"Mâu thuẫn chủ yếu của xã hội Việt Nam đầu thế kỷ XX là gì?",["Mâu thuẫn giữa dân tộc Việt Nam với đế quốc xâm lược và phong kiến tay sai của chúng.","Mâu thuẫn giữa giai cấp nông dân với giai cấp địa chủ phong kiến.","Mâu thuẫn giữa giai cấp công nhân với giai cấp tư sản.","Mâu thuẫn giữa giai cấp nông dân và giai cấp công nhân với đế quốc và phong kiến"],"a",""],[327,"Chiến tranh đặc biệt được Mỹ thực hiện ở Miền Nam Việt Nam vào thời gian nào?",["1956-1960","1961-1965","1965-1968","1969-1972"],"b",""],[328,"Mâu thuẫn chủ yếu ở Việt Nam cuối thế kỳ XIX đầu thế kỳ XX là mâu thuẫn giữa:",["Địa chủ phong kiến vối nông dân","Tư sản với công nhân","Tư sản Việt Nam vối tư sản Pháp","Dân tộc Việt Nam với đế quốc Pháp"],"d",""],[329,"Cách mạng tháng Tám (1945) là cuộc cách mạng:",["Tư sản","Xã hội chủ nghĩa","Giải phóng dân tộc","Ruộng đất"],"c",""],[330,"Đường lối kháng chiến chống Pháp của Đảng được thể hiện tập trung trong những văn kiện nào?",["Chỉ thị toàn dân kháng chiến; Lời kêu gọi toàn quốc kháng chiến, tác phẩm \" Kháng chiến nhất định thắng lợi\"","Chỉ thị \" Kháng chiến kiến quốc\"; Lời kêu gọi toàn quốc kháng chiến, tác phẩm \" Kháng chiến nhất định thắng lợi\"","Chỉ thị Toàn dân kháng chiến, Lời kêu gọi Toàn quốc kháng chiến","Tuyên ngôn độc lập, Lời kêu gọi toàn quốc kháng chiến, tác phẩm \" Kháng chiến nhất định thắng lợi\""],"a",""],[331,"Ngày 18/3/1975, Bộ Chính trị quyết định:",["Giải phóng miên Nam trong năm 1975","Giải phóng miên Nam trong hai năm 1975 - 1976","Giải phóng miền Nam trong tháng 4 năm 1975","Giài phóng miền Nam trước mùa mưa năm 1975"],"a",""],[332,"Đảng chủ trương thành lập Mặt trận nào vào tháng 7/1936?",["Mặt trận dân chủ Đông Dương","Mặt trận Việt Minh","Mặt trận Liên Việt","Mặt trận Thống nhất dân tộc phản đế Đông Dương"],"a",""],[333,"Ngày 2/9/1945 gắn với sự kiện lịch sử nào?",["Pháp xâm lược nước ta lần 2","Ngày Nam Bộ kháng chiễn","Chủ tịch Hồ Chí Minh đọc tuyên ngôn độc lập khai sinh nước Việt Nam Dân chủ Cộng hòa","Ngày toàn quốc kháng chiến chống thực dân Pháp xâm lược"],"c",""],[334,"Đâu không phải là bài học kinh nghiệm mà Đại hội Đảng lần thứ X đã rút ra?",["Đổi mới toàn diện,đồng bộ có kế thừa, bước đi, hình thức cách làm phù hợp","Đổi mới phải vì lợi ích của nhân dân, dựa vào dân, phát huy vai trò chủ động, sáng tạo của nhân dân, xuất phát từ thực tiễn, nhạy bén với cái mới.","Phát huy cao độ nội lực, ra sức khai thác ngoại lực, kết hợp sức mạnh dân tộc và thời đại trong điều kiện mới.","Lấy đổi mới chính trị làm thứ yếu, đồng thời từng bước đổi mới kinh tế."],"d",""],[335,"Hội nghị Trung ương 6 (8/1979) được coi là bước đột phá đầu tiên của Đảng trong lĩnh vực:",["Đổi mới kinh tế","Đổi mới hệ thống chính trị","Đổi mới đưởng lối đối ngoại","Đổi mới đường lỗi văn hóa văn nghệ"],"a",""],[336,"Nghị quyết Hội nghị Trung ương 2 khóa VIII (12/1996) coi khoa học và công nghệ, giáo dục và đào tạo là:",["Quốc sách chiên lược","Quốc sách hàng đầu","Quốc sách đặc biệt","Quốc sách quan trọng nhất"],"b",""],[337,"Trong giai đoạn 1965 - 1968, ở miền Nam, Mỹ đã thực hiện chiến lược chiến tranh nào?",["Chiến tranh đơn phương","Chiến tranh đặc biệt","Chiến tranh cục bộ","Việt Nam hóa chiến tranh"],"c",""],[338,"Hội nghị Trung ương III, khóa VIII (1997) của Đảng đã chủ trương:",["Thực hiện thẳng lợi sự nghiệp công nghiệp hóa, hiện đại hóa","Xây dựng đội ngũ cán bộ các cấp có phẩm chất và năng lực, có bản lĩnh chính trị vũng vàng","Xây dựng đội ngũ cán bộ các cấp có phẩm chất và năng lực, có bản lĩnh chính trị vũng vàng, đủ về số lượng, đông bộ về cơ cấu","Liên minh công nhân, nông dân và tầng lớp trí thức"],"c",""],[339,"Vận mệnh của dân tộc Việt Nam ngay sau khi Cách mạng tháng Tám thành công được Chủ tịch Hồ Chí Minh đánh giá:",["Có những thách thức to lớn","Vô cùng khó khăn, nguy hiểm","Vô cùng hiểm nghèo","Ngàn cân treo sợi tóc"],"d",""],[340,"Nước Việt Nam Dân chủ Cộng hòa thiết lập quan hệ ngoại giao với Trung Quốc, Liên Xô và các nước xã hội chủ nghĩa Đông Âu vào năm:",["1949","1950","1951","1952"],"b",""],[341,"Đại hội lần thứ III của Đảng (9/1960) xác định cách mạng Việt Nam trong giai đoạn mới phải đồng thời thực hiện mấy chiến lược cách mạng?",["2","3","4","5"],"a",""],[342,"Vì sao trong thời kì đổi mới đất nước nhưng vẫn phải tiếp tục xây dựng giai cấp công nhân Việt Nam?",["Giai cấp công nhân là động lực phát triển kinh tế","Giai cấp công nhân đại diện cho phương thức sản xuất hiện đại","Giai cấp lãnh đạo cách mạng thông qua đội tiền phong là Đảng Cộng sản Việt Nam, là giai cấp đại diện cho phương thức sản xuất tiên bộ","Giai cấp công nhân là giai cấp lãnh đạo cách mạng thông qua đội tiền phong là Đảng Cộng sản Việt Nam,là giai cấp đại diện cho phương thức sản xuất tiên tiến, tiên phong đi đầu trong sự nghiệp công nghiệp hóa - hiện đại hóa đất nước"],"d","(Kiểu hỏi khác: Vì sao đất nước đã độc lập vẫn xây dựng giai cấp công nhân Việt Nam trong thời kỳ đẩy mạnh công nghiệp hóa- hiện đại hóa đất nước? A. cấp công nhân là động lực phát triển kinh tế B. Giai cấp công nhân đại diện cho phương thức sản xuất hiện đại. C. Giai cấp lãnh đạo cách mạng thông qua đội tiền phong là Đảng Cộng sản Việt Nam , là giai cấp đại diện cho phương thức sản xuất tiên bộ. D. Giai cấp lãnh đạo cách mạng thông qua đội tiền phong là Đảng Cộng sản Việt Nam, là giai cấp đại diện cho phương thức sản xuất tiên tiến, tiên phong đi đầu trong sự nghiệp công nghiệp hóa- hiện đại hóa đất nước.)"],[343,"Công nghiệp hóa - hiện đại hóa đất nước là sự nghiệp của:",["Toàn dân","Đảng Cộng sản Việt Nam","Cơ quan quản lý nhà nước về văn hóa","Nhà nước Việt Nam"],"a",""],[344,"Khởi nghĩa thắng lợi ở địa phương nào đã tạo điều kiện quyết định cho Tổng khởi nghĩa thành công trên cả nước trong Cách mạng tháng Tám (1945)?",["Thái Nguyên","Hà Nội","Huế","Sài Gòn"],"b",""],[345,"Sự kiện nào được lãnh tụ Nguyễn Ái Quốc đánh giá \"nó chứng tỏ rằng giai cấp vô sản ta đã trường thành và đủ sức lãnh đạo cách mạng\"?",["Quốc tế Cộng sản ra đời (1919)","Hội Việt Nam Cách mạng Thanh niên ra đời (1925)","Ba tổ chức cộng sản ra đời (1929)","Đảng Cộng sản Việt Nam ra đời (1930)"],"d",""],[346,"Chính sách phát triển kinh tế được Đảng đề ra tại Đại hội VI (1986) là:",["Tự cung tự cấp","Kế hoạch hóa tập trung","Kinh tế thị trường","Kinh tế nhiều thành phần"],"d",""],[347,"Mục tiêu cụ thế trước mắt của cao trào cách mạng 1936 - 1939 là:",["Độc lập dân tộc","Ruộng đất cho dẫn cày","Đánh đổ chế độ thực dân, phong kiến","Các quyền dân chủ đơn sơ"],"d",""],[348,"Ai là Tư lệnh Chiến dịch Hồ Chí Minh giải phóng Sải Gòn - Gia Định tháng 4/1975?",["Lê Trọng Tần","Văn Tiến Dũng","Trân Văn Trà","Hoàng Văn Thái"],"b",""],[349,"Đại hội lần thứ II Đảng Cộng sản Đông Dương (1951) đã quyết định:",["Giữ nguyên Đảng Cộng sản Đông Dương","Đổi tên thành Đảng Lao động Việt Nam","Thành lập chính đảng cách mạng riêng ở 2 nước Lào và Campuchia","Chi thành lập chính đàng cách mạng ở Việt Nam"],"bc",""],[350,"Sau khi Mỹ thực hiện chiến lược \"Chiến tranh cục bộ\", Đảng nhân định tình hình:",["Đây là cuộc chiến tranh xâm lược thực dân mới, buộc phải thực thi trong thế thua, thế thất bại và bị động cho nên nó chủa dựng đầy mâu thuẫn chiến lược","Đây là cuộc chiến tranh xâm lược thực dân cũ, buộc phải thực thi trong thế thua, thế thất bại và bị động cho nên nó chứa đựng đây mâu thuẫn chiến lược","Đây là cuộc chiến tranh xâm lược thực dân hiện đại, buộc phải thực thi trong thế thua, thế thất bại và bị động cho nên nó chứa đựng đầy mâu thuẫn chiến lược"],"a",""],[351,"Chủ trương nào không có trong Chỉ thị \"Nhật - Pháp bắn nhau và hành động của chúng ta\" (3/1945)?",["Thông qua 10 chính sách lớn của Việt Minh","Thay khẩu hiệu \"đánh đuổi phát xít Nhật - Pháp\" bằng khẩu hiệu \"đánh đuổi phát xít Nhật\"","Nêu khẩu hiệu \"thành lập chính quyên cách mạng của nhân dân Đông Dương\"","Phát động một cao trào kháng Nhật cứu nước"],"a",""],[352,"Tại Đại hội nào, lần đầu tiên Đảng giương cao ngọn cờ tư tường Hồ Chí Minh và khăng định \"lấy chủ nghĩa Mác - Lênin và tư tưởng Hồ Chí Minh làm nên tàng tư tưởng và kim chi nam cho hành động\"?",["Đại hội VI (1986)","Đại hội VII (1991)","Đại hội VIII (1996)","Đại hội IX (2001)"],"b",""],[353,"Quan điểm nào sau đây của Đảng về nhiệm vụ và mỗi quan hệ giữa hai miền sau khi Mỹ thực hiện \"chiến tranh cục bộ\"?",["Trong cuộc chiến tranh chống Mỹ của nhân dân cà nước, miền Nam là tiền tuyến lớn, miền Bắc là hậu phương lớn. Bảo vệ miền Bắc là nhiệm vụ của cả nước","Trong cuộc chiến tranh chống Mỹ của nhân dân cà nước, miền Nam là hậu phương lôn, miền Bắc là tiền tuyến lớn. Bảo vệ miền Bắc là nhiệm vụ của cả nước","Trong cuộc chiến tranh chống Mỹ của nhân dân cà nước, miền Nam là tiền tuyến lôn, miễn Bắc là hậu phương lớn. Bảo vệ miền Bắc là nhiệm vụ của miễn Bắc","Trong cuộc chiến tranh chống Mỹ của nhân dân cà nước, miền Nam là tiên tuyến lôn, miễn Bắc là hậu phương lớn. Bảo vệ miền Bắc là nhiệm vụ của miễn Nam"],"a",""],[354,"Tại sao cuộc tổng tiến công nổi dậy Mậu Thân 1968 bị thất bại vừa mất đất, mất dân, hy sinh nhiều nhưng Đảng ta vẫn đánh giá thành công?",["Chúng ta đã giáng đòn lớn và mạnh buộc Mỹ ngồi vào bàn đàm phán.","Chúng ta đã giáng đòn lớn và mạnh buộc Mỹ kí hiệp định Pari.","Buộc Mỹ phải thừa nhận thất bại của chiến lược Việt Nam hóa chiến tranh.","Mỹ buộc phải rút quân về nước."],"a",""],[355,"Thực tiễn 30 năm chiến tranh cách mạng Việt Nam (1945 - 1975) cho thấy: hậu phương của chiến tranh nhân dân",["không thể phân biệt rạch ròi với tiền tuyến chỉ bằng yếu tố không gian.","ở phía sau và phân biệt rạch ròi với tiền tuyến bằng yếu tố không gian.","luôn ở phía sau và bảo đảm cung cấp sức người, sức của cho tiền tuyến.","là người bạn của tiền tuyến, thực hiện nhiệm vụ chi viện cho tiền tuyến."],"a",""],[356,"Hội nghị Trung ương 8 (5/1941) đã bầu ai làm Tổng Bí thư của Đảng?",["Nguyễn Ái Quốc","Nguyễn Văn Cừ","Trường Chinh","Lê Duẩn"],"c",""],[357,"Chủ trương cho phép đảng viên lầm kinh tế tư nhân được Đảng chính thức thông qua tại Đại hội lần thứ mấy?",["Đại hội IX (2001)","Đại hội X (2006)","Đại hội XI (2011)","Đại hội XII (2016)"],"b",""],[358,"Theo quan điểm của đại hội đảng lần thứ IV (12/1976), đặc điểm nào sau đây là lớn nhất, quy định nội dung, hình thức, bước đi của cách mạng xã hội chủ nghĩa ở nước ta trong giai đoạn mới",["Tổ quốc ta đã hòa bình, độc lập, thống nhất, cả nước tiến lên chủ nghĩa xã hội","Cách mạng xã hội chủ nghĩa ở nước ta tiến hành trong hoàn cảnh quốc tế thuận lợi","Nước ta đang ở trong quá trình từ một xã hội mà nền kinh tế còn phổ biến là sản xuất nhỏ tiến thẳng lên chủ nghĩa xã hội, bỏ qua giai đoạn phát triển tư bản chủ nghĩa","Đất nước còn đối mặt nhiều khó khăn do hậu quả của chiến tranh và tàn dư của chủ nghĩa thực dân"],"a",""],[359,"Đặc điểm của nước Việt Nam dân chủ cộng hòa ngay khi ra đời là:",["Được các nước lớn công nhận","được liên hợp quốc công nhận","không được sự ủng hộ của các nước đồng minh","gắn liền với hậu phương xã hội chủ nghĩa"],"c",""],[360,"Cuộc tổng tiến công và nổi dậy mùa xuân 1975 bắt đầu bằng chiến dịch nào",["Chiến dịch Mậu Thân (1968)","chiến dịch Tây Nguyên (3/1975)","chiến dịch Huế-ĐN (3/1975)","chiến dịch Hồ Chí Minh (4/1975)"],"b",""],[361,"Giai cấp công nhân muốn trở thành lực lượng lãnh đạo cách mạng trước hết phải",["Thành lập ra chính đảng của nó","Thành lập ra mặt trận của nó","Thành lập ra tổ chức của nó","Thành lập ra đoàn thể của nó"],"a",""],[362,"Đặc điểm lớn nhất của thời kỳ quá độ lên chủ nghĩa xã hội ở nước ta là",["Năng suất lao động thấp.","Lực lượng sản xuất chưa phát triển","Nhiều thành phần xã hội đan xen tồn tại","Từ một nền sản xuất nhỏ là phổ biến quá độ lên CNXH không qua chế độ TBCN"],"d",""],[363,"Bản Hiến pháp đầu tiên của nước Việt Nam Dân chủ cộng hòa được thông qua vào thời gian nào sau đây",["9/11/1945","2/9/1945","12/12/1946","9/11/1946"],"d",""],[364,"Năm 1932, được sự chỉ đạo của Quốc tế Cộng sản, ban lãnh đạo của đảng ở nước ngoài do ai đứng đầu?",["Lê Hồng Phong","Hà Huy Tập","Trường Chinh","Trần Phú"],"a",""],[365,"Hiệp định Pa-ri về chấm dứt chiến tranh lập lại hòa bình ở Việt Nam được ký kết vào thời gian nào sau đây:",["20/7/1954","22/12/1954","27/7/1973","27/1/1973"],"d",""],[366,"Chính sách cai trị thời chiến được Pháp thi hành vào giai đoạn nào?",["1936-1939","1939-1945","1945-1954","1930-1935"],"b",""],[367,"Sự kiện nào mở đầu cho giai đoạn \"dàn hòa với Pháp\" để đẩy nhanh quân Tưởng về nước thời kỳ 1945 - 1946?",["Pháp ngừng bắn ở Nam Bộ (10/1945)","Ký Hiệp định Sơ bộ Việt - Pháp (3/1946)","Chủ tịch Hồ Chí Minh thăm Pháp (5/1946)","Đàm phán chính thức Việt - Pháp ở Phôngtennoblô (7/1946)"],"b",""],[368,"Việt Nam chính thức thiết lập quan hệ ngoại giao với Mỹ vào thời gian nào?",["1990","1994","1995","2000"],"c",""],[369,"Sau khi lên cầm quyền (1969), Tổng thống Mỹ R. Ních xơn chủ trương thay chiến lược Chiến tranh cục bộ ở miền Nam bằng chiến lược:",["Chiến tranh tổng lực","Chiến tranh đơn phương","Chiến tranh đặc biệt","Việt Nam hóa chiến tranh"],"d",""],[370,"Cuối năm 1974, đầu năm 1975, Bộ Chính trị đã đề ra mấy kế hoạch khi hạ quyết tâm giải phóng miền Nam trong hai năm 1975 - 1976?",["1","2","3","4"],"b",""],[371,"Nhiệm vụ đầu tiên, bức thiết nhất được Đảng xác định sau thắng lợi mùa Xuân năm 1975 là",["Khôi phục và phát triển kinh tế","Khắc phục hậu quả chiến tranh","Xây dựng Miền Nam Việt Nam thành một nước hòa bình, trung lập","Thống nhất nước nhà về mặt Nhà nước"],"d",""],[372,"Nhiệm vụ kinh tế trọng tâm ở miền Bắc sau tháng 7/1954 được Đảng xác định",["Khôi phục và phát triển sản xuất nông nghiệp","Khôi phục và phát triển sản xuất công nghiệp","Khôi phục và phát triển tiểu thủ công nghiệp","Khôi phục và phát triển thương nghiệp"],"a",""],[373,"Khẩu hiệu được Đảng đề ra trong giai đoạn giữ vững và củng cố chính quyền cách mạng 1945 - 1946 là",["Việt Nam độc lập muôn năm","Dân tộc trên hết, Tổ quốc trên hết","Đoàn kết, đoàn kết, đại đoàn kết","Mặt trận Việt Minh muôn năm"],"b",""],[374,"Một trong những nhiệm vụ trọng tâm mà Đại hội XII đã nêu (2011-2018) là",["Đẩy mạnh công nghiệp hóa xã hội chủ nghĩa, xây dựng cơ sở vật chất - kỹ thuật của chủ nghĩa xã hội, đưa nền kinh tế nước ta từ sản xuất lớn lên sản xuất đại quy mỗ xã hội chủ nghĩa","Sự nghiệp của nhà nước và các doanh nghiệp liên doanh","Sự nghiệp của toàn dân, của mọi thành phần kinh tế, trong đó kinh tế nhà nước là chủ đạo","Tập trung thực hiện các giải pháp nâng cao chất lượng tăng trưởng, năng suất lao động và sức cạnh tranh của nền kinh tế"],"d",""],[375,"Thống nhất nước nhà về mặt Nhà nước sau năm 1975 là",["Thống nhất giữa Chính phủ Việt Nam Dân chủ Cộng hòa với Chính phủ Việt Nam Cộng hòa","Thống nhất giữa Chính phủ Việt Nam Dân chủ Cộng hòa với Chính phủ Cách mạng Lâm thời Cộng hòa Miền Nam Việt Nam","Thống nhất giữa Chính phủ Việt Nam Dân chủ Cộng hòa với Mặt trận Dân tộc Giải phóng Miền Nam Việt Nam","Thống nhất giữa Đảng Lao động Việt Nam với Đảng Nhân dân Cách mạng Miền Nam Việt Nam"],"b",""],[376,"Đại hội lần thứ VII Quốc tế Cộng sản (7/1935) xác định kẻ thù nguy hiểm trước mắt của nhân dân thế giới là:",["Chủ nghĩa phát xít","Chủ nghĩa đế quốc","Chủ nghĩa tư bản","Chủ nghĩa Tờ rốt kít"],"a",""],[377,"Quan điểm mới nổi bật của Đại hội Đảng lần thứ X (2006) là đã cho phép:",["Đảng viên làm kinh tế tư nhân","Đảng viên tự ứng cứ và đê cử","Đảng viên được tự do xuất cảnh","Đảng viên được tự do kết hôn với người nước ngoài"],"a",""],[378,"Đại hội XII của Đảng (2016) nêu rõ mục tiêu, nhiệm vụ tổng quát phát triển đất nước 5 năm 2016 - 2020 là:",["Đổi mới thể chế kinh kế","Đối mới mô hình tăng trường","Đối mới hệ thống chính trị","Đưa nước ta trở thành nước công nghiệp theo hướng hiện đại vào năm 2020"],"b",""],[379,"Định hướng phát triên đất nước đến năm 2030 mà Đại hội XIII của Đảng xác định là:",["Nước đang phát triển có công nghiệp theo hướng hiện đại vượt qua mức thu nhập trung bình thấp","Nước đang phát triển có công nghiệp hiện đại thu nhập trung bình cao","Nước đang phát triển có công nghiệp theo hướng hiện đại","Nước phát triển có thu nhập cao"],"b",""],[380,"Mô hình kinh tế tổng quát của nước ta trong thời kỳ quá độ lên chủ nghĩa xã hội được Đại hội IX của Đảng (2001) xác định là:",["Kinh tế thị trường tự do","Kinh tế hàng hóa nhiều thành phần","Kinh tế thị trường định hướng xã hội chủ nghĩa","Kinh tế nhà nước và kinh tế tập thể"],"c",""],[381,"Đại hội nào của Đảng lần đầu tiên đề ra hai nhiệm vụ chiến lược của cách mạng Việt Nam là xây dựng thành công chủ nghĩa xã hội và bảo vệ vũng chắc Tổ quốc Việt Nam xã hội chủ nghĩa?",["Đại hội IV (1976)","Đại hội V (1982)","Đại hội VI (1986)","Đại hội VII (1991)"],"b","(Kiểu hỏi khác: Đại hội đại biểu toàn quốc lần thứ mấy của Đảng Cộng sản Việt Nam lần đầu tiên đề cập đến hai nhiệm vụ chiến lược là xây dựng chủ nghĩa xã hội và bảo vệ Tổ quốc?)"],[382,"Hội nghị Trung ương 13 (1/1967) chủ trương mở mặt trận nào để tiến công địch?",["Mặt trận chính trị","Mặt trận quân sự","Mặt trận binh vận","Mặt trận ngoại giao"],"d",""],[383,"Trong giai đoạn 1947- 1949, cuộc kháng chiến chống Pháp của nhân dân ta dựa vào:",["Sự giúp đỡ của Liên Xô là chính","Sự giúp đỡ của Đảng Cộng sản Trung Quốc là chính","Sự giúp đỡ của Liên hợp quốc là chính","Sức mình là chính"],"d",""],[384,"Hội nghị Trung ương 5 khóa XII (5/2017) ban hành nghị quyết vẽ phát triên kinh tê tư nhân, trong đó xác định:",["Kinh tế tư nhân là một động lực quan trọng để phát triến kinh tế","Kinh tế tư nhần giữ vai trò chủ đạo của nên kinh tế","Kinh tế tư nhân là trụ cột của nền kinh tế","Kinh tế tư nhân giữ vai trò quyết định trong phát triên kinh tế"],"a",""],[385,"Đại hội Đảng lần thứ IV (12/1976) đã nêu lên mấy đặc điểm lớn của cách mạng Việt Nam trong giai đoạn mới?",["2","3","4","5"],"b",""],[386,"Nghị quyết số 10-NQ/TW ngày 5/4/1988 của Bộ Chính trị là nghị quyết chuyên đề về:",["Đổi mới quản lý kinh tế công nghiệp","Đổi mới quản lý kinh tế thương nghiệp","Đổi mới quản lý kinh tế dịch vụ","Đổi mới quản lý kinh tế nông nghiệp"],"d",""],[387,"Tuyến vận tài chiến lược Trường Sơn - đường mòn Hồ Chí Minh trên bộ chi viện miền Nam đánh Mỹ hình thành vào năm:",["1958","1959","1960","1961"],"b",""],[388,"Sự kiện nào đánh dấu Nguyễn Ái Quốc bước đầu tìm thấy con đường cứu nước đúng đắn cho dân tộc Việt Nam?",["Nguyễn Ái Quốc đưa yêu sách đến Hội nghị Véc-xai (18/6/1919)","Nguyễn Ái Quốc tham gia sáng lập Đảng Cộng sản Pháp (25/12/1925)","Nguyễn Ái Quốc đọc bản Sơ thảo lần thứ nhất những Luận cương về vấn đề dân tộc và thuộc địa của Lênin (7/1920)","Nguyễn Ái Quốc thành lập tổ chức Hội Việt Nam Cách mạng Thanh niên (6/1925)"],"c",""],[389,"Lãnh tụ Nguyễn Ái Quốc dùng hình ảnh \"con chim có hai cánh\" để chỉ mỗi quan hệ giữa:",["Phong trào đấu tranh của giai cấp công nhân với phong trào đấu tranh của giai cấp nông dân thuộc địa","Phong trào đấu tranh của giai cấp công nhân ở các nước chính quốc với phong trào đấu tranh dân tộc ở các nước thuộc địa","Phong trào đấu tranh giữa giai cấp tư sản và giai cấp vô sản ở các nước chính quốc","Chính sách bóc lột của chủ nghĩa đễ quốc ở chính quốc và thuộc địa"],"b",""],[390,"Ngày 25/3/1975, Bộ Chính trị bổ sung quyết tâm chiến lược giải phóng miền Nam:",["Trong năm 1975","Cuối năm 1975","Tháng 4 năm 1975","Trước mùa mưa năm 1975"],"d",""],[391,"Quốc dân Đại hội Tân Trào được triệu tập bởi:",["Quốc tế Cộng sản","Đàng Cộng sản Đông Dương","Lãnh tụ Hồ Chí Minh","Tổng bộ Việt Minh"],"d",""],[392,"Mỗi quan hệ giữa hai nhiệm vụ cách mạng của hai miền được Đại hội III của Đảng xác định là:",["Hai nhiệm vụ chiến lược ấy có quan hệ mật thiết với nhau và có tác dụng thúc đẩy lẫn nhau","Hai nhiệm vụ chiến lược ấy có quan hệ quyết định lẫn nhau","Hai nhiệm vụ chiến lược ấy có quan hệ mật thiết với nhau","Hai nhiệm vụ chiến lược ấy có quan hệ độc lập với nhau và có tác dụng thúc đẩy lẫn nhau"],"a",""],[393,"Đại hội lần thứ I Đảng Cộng sản Đông Dương được tổ chức tại",["Quảng Chẫu","Hồng Công","Ma Cao","Thượng Hài"],"c",""],[394,"Nguyên tắc tổ chức cơ bản của Đảng Cộng sản Việt Nam là:",["Dân chủ","Tập trung","Dân chủ tập trung","Tập trung dân chủ"],"d",""],[395,"Thành quả quan trọng nhất của cuộc Tổng tiến công và nổi dậy Tết Mậu Thân (1968) là:",["Đánh bại ý chí xâm lược của Mỹ","Đánh bại quân đội Mỹ trên chiến trường","Đánh bại quân đội Sài Gòn","Đánh đồ chính quyền Sài Gòn"],"a",""],[396,"Ai là người ban hành mệnh lệnh \"thần tốc, thần tốc hơn nữa, táo bạo, táo bạo hơn nữa, tranh thủ từng phút, từng giờ, xốc tới mặt trận, giải phóng miền Nam. Quyết chiến và toàn thắng\"?",["Võ Nguyên Giáp","Văn Tiến Dũng","Trần Văn Trà","Hoàng Văn Thái"],"a",""],[397,"Đại hội VI của Đàng (1986) đã bầu ai làm Tổng Bí thư?",["Trường Chinh","Phạm Văn Đồng","Nguyễn Văn Linh","Đỗ Mười"],"c",""],[398,"Phiên họp đầu tiên của Chính phủ Lâm thời Việt Nam Dân chủ Cộng hòa ngày 3/9/1945 xác định mấy nhiệm vụ lớn trước mắt của chính quyền cách mạng?",["2","3","4","5"],"d","(Giải thích: RA ĐỀ NGU NHƯ BÒ NẾU ĐÚNG THÌ PHẢI LÀ 6)"],[399,"Lãnh tụ Nguyễn Ái Quốc đã đề cập những vấn đề cơ bản của một cương lĩnh chính trị, qua đó chuẩn bị về tư tưởng chính trị cho việc thành lập Đảng thông qua tác phẩm nào?",["Đường Kách Mệnh","Bản án chế độ thực dân Pháp","Đông Dương","Điều lệ vắn tắt, Chương trình tóm tắt của Đảng"],"a",""],[400,"Đâu là hạn chế của Đảng khi đề ra đường lối cách mạng xã hội chủ nghĩa tại Đại hội lần thứ III (9/1960)?",["Chưa hoàn chỉnh đường lỗi chiến lược chung của cách mạng Việt Nam","Chưa đề ra chiến lược cách mạng riêng ở 2 miền","Chưa có dự kiến về chặng đường đầu tiên của thời kỳ quá độ lên chủ nghĩa xã hội","Nhận thức về con đường đi lên chủ nghĩa xã hội còn giản đơn"],"d",""],[401,"Năm 1929, Hội Việt Nam Cách mạng Thanh niên phân hóa thành:",["An Nam Cộng sản Đảng","Đông Dương Cộng sản Đảng","Đông Dương Cộng sản Liên đoàn","Đảng Cộng sản Việt Nam"],"ab",""],[402,"Đâu không phải là điều kiện tạo nên thời cơ cách mạng chín muồi của Tổng khởi nghĩa tháng Tám năm 1945 ở Việt Nam?",["Phát xít Nhật đảo chính lật đồ Pháp ở Đông Dương","Đảng và quần chúng nhân dân đã sẵn sàng hành động","Lực lượng trung gian đã ngà hẳn về phía cách mạng","Phát xít Nhật đầu hàng quân Đồng minh không điều kiện"],"a","(Giải thích: Nhật đảo chính Pháp ở Đông Dương đã tạo ra cuộc khủng hoảng chính trị sâu sắc ở Đông Dương nhưng thời cơ tổng khởi nghĩa vẫn chưa chín muồi -> Đảng ta mới phát động cao trào kháng Nhật cứu nước.)"],[403,"\"Cuộc cách mạng Đông Dương hiện tại không phải là cuộc cách mạng tư sản dẫn quyền, cuộc cách mạng phải giải quyết hai vấn đề phản đế và điền địa nữa, mà là cuộc cách mạng chỉ phải giải quyết một vấn đề cần kíp \"dẫn tộc giài phóng\". Chủ trương trên của Đảng được khẳng định tại Hội nghị nào?",["Hội nghị Ban Chấp hành Trung ương tháng 11/1939","Hội nghị Cán bộ Trung ương tháng 11/1940","Hội nghị Ban Chấp hành Trung ương tháng 5/1941","Hội nghị Ban Thường vụ Trung ương tháng 3/1945"],"c",""],[404,"Sự kiện nào diễn ra vào ngày 19 tháng 8 năm 1945, đánh dấu sự khởi đầu của cuộc Cách mạng tháng Tám?",["Khởi nghĩa ở Hà Nội","Khởi nghĩa ở Sài Gòn","Khởi nghĩa ở Huế","Khởi nghĩa ở Nghệ-Tĩnh"],"a",""],[405,"Lãnh tụ Nguyễn Ái Quốc sáng lập tờ báo Le Paria và viết nhiều bài trên đó là sự chuẩn bị cho sự ra đời của Đảng Cộng sản Việt Nam về mặt nào?",["Tư tưởng","Chính trị","Tổ chức","Đạo đức"],"a",""],[406,"Khẩu hiệu \"Dân tộc trên hết, Tổ quốc trên hết\" là cơ sở tư tưởng cho hệ thống chính trị nào ở nước ta?",["Dân chủ xã hội chủ nghĩa","Dân chủ nhân dân","Dân tộc dân chủ","Độc lập dân tộc"],"b",""],[407,"Ngày 24/2/1930, Quyết nghị của Lâm thời Chấp ủy Đảng Cộng sản Việt Nam chấp nhận tổ chức nào gia nhập Đảng?",["Đông Dương Cộng sản Đảng","Đông Dương Cộng sản Liên đoàn","An Nam Cộng sản Đảng","Việt Nam Quốc dân Đảng"],"b",""],[408,"Các cuộc khai thác thuộc địa của thực dân Pháp đã làm xuất hiện ở Việt Nam những giai cấp, tầng lớp mới nào?",["Địa chủ phong kiến, nông dân, công nhân","Nông dân, công nhân, tiểu tư sản","Công nhân, tiểu tư sản, tư sản dân tộc","Tiểu tư sản, tư sản dân tộc, tiểu địa chủ"],"c",""],[409,"Trong cuộc xâm lược Việt Nam từ 1858 đến 1945, thực dân Pháp đã tiến hành mấy cuộc khai thác thuộc địa?",["1","2","3","4"],"b",""],[410,"Chiến dịch Điện Biên Phủ bắt đầu vào ngày nào và kết thúc vào ngày nào?",["Bắt đầu 13/3/1954, kết thúc 7/5/1954","Bắt đầu 1/4/1954, kết thúc 2/5/1954","Bắt đầu 15/3/1954, kết thúc 25/5/1954","Bắt đầu 2/3/1954, kết thúc 10/5/1954"],"a",""],[411,"Động lực cách mạng trong Cương lĩnh chính trị đầu tiên của Đảng ta xác định bao gồm những lực lượng nào? (Chọn 2)",["Giai cấp công nhân","Giai cấp tư sản mại bản","Giai cấp tư sản dân tộc","Giai cấp nông dân"],"ad","(Giải thích: Cương lĩnh chính trị đã xác định lực lượng cách mạng là: công nhân, nông dân, tiểu tư sản, trí thức. Còn phú nông, trung và tiểu địa chủ thì lợi dụng hoặc trung lập họ.)"],[412,"\"Chiến tranh có thể kéo dài 5 năm, 10 năm, 20 năm hoặc lâu hơn nữa. Hà Nội, Hải Phòng và một số thành phố, xí nghiệp có thể bị tàn phá, song người Việt Nam quyết không sợ. Không có gì quý hơn độc lập, tự do\". Khẳng định trên của Chủ tịch Hồ Chí Minh được viết trong tác phẩm nào?",["Lời kêu gọi","Đường cách mệnh","Tuyên ngôn độc lập","Di chúc"],"a",""],[413,"Nguyễn Tất Thành tham gia Đảng Xã hội Pháp vào thời gian nào?",["Năm 1919","Năm 1920","Năm 1921","Năm 1922"],"a",""],[414,"Một trong những nội dung kinh nghiệm của Đảng về lãnh đạo kháng chiến chống thực dân Pháp và can thiệp của Mỹ đó là?",["Đẩy mạnh phát triển cuộc kháng chiến về mọi mặt.","Đánh đuổi bọn đế quốc xâm lược, giành độc lập và thống nhất thật sự cho dân tộc.","Đề ra đường lối đúng đắn, sáng tạo, phù hợp với thực tiễn lịch sử của cuộc kháng chiến ngay từ những ngày đâu.","Kết hợp đấu tranh quân sự và ngoại giao, kết thúc thắng lợi cuộc kháng chiến"],"c","(Kiểu hỏi khác: Kết hợp chặt chẽ và giài quyết đúng đắn mối quan hệ giữa hai nhiệm vụ cơ bàn vừa kháng chiến vừa kiến quốc, chống đế quốc và chống phong kiến, được xác định là gì? A. Ý nghĩa thắng lợi của kháng chiến chong thực dân Pháp và can thiệp của Mỹ. B. Đường lối kháng chiến của Đàng. C. Nội dung đấu tranh xây dụng củng cố chính quyền cách mạng. D. Kinh nghiệm của Đảng về lãnh đạo kháng chiến chống thực dân Pháp và can thiệp của Mỹ.)"],[415,"Sau Hiệp định Giơnevo (7/1954) cách mạng Việt Nam có những thuận lợi gì?",["Hệ thống chủ nghĩa xã hội lớn mạnh.","Phong trào giải phóng dân tộc trên thế giới lên cao.","Miền Bắc được hoàn toàn giải phóng, làm hậu phương lớn cho cả nước kháng chiến.","Mỹ âm mưu bá chủ toàn cầu"],"abc",""],[416,"Trung Quốc cho quân đội chiếm đảo Gạc Ma và các bãi cạn Châu Viên, Chữ Thập, Tư Nghĩa ở quần đảo Trường Sa của Việt Nam vào thời gian nào?",["Tháng 3/1988.","Tháng 3/1986.","Tháng 3/1987.","Tháng 2/1979."],"a",""],[417,"Phần đầu đến giữa thế kỷ XXI, nước ta trở thành nước phát triển theo định hướng xã hội chủ nghĩa. Được đề cập trong Đại hội lần thứ mấy của Đảng Cộng sản Việt Nam?",["Đại hội Đảng lần thứ XIII.","Đại hội Đảng lần thứ XII.","Đại hội Đảng lần thứ XI.","Đại hội Đảng lần thứ X."],"a",""],[418,"Đâu là nhận định đúng khi đề cập đến Đại hội lần thứ IV của Đảng trong các nhận định sau đây?",["Là Đại hội toàn thắng của sự nghiệp giải phóng dân tộc, thống nhất Tổ quốc","Đại hội khẳng định và xác định đường lối đưa miền Bắc tiến lên chủ nghĩa xã hội","Đại hội đã nhìn thẳng vào sự thật, đánh giá đúng sự thật, nói rõ sự thật","Là Đại hội đổi mới toàn diện, đưa đất nước thoát khỏi khủng hoảng kinh tế - xã hội"],"a",""],[419,"Vì sao Mỹ buộc phải tuyên bố ngừng hẳn ném bom, bắn phá miền Bắc lần thứ nhất?",["Thất bại trong chiến lược \"Chiến tranh cục bộ\" ở miền Nam","Thất bại nặng nề trong chiến tranh phá hoại miền Bắc","Thất bại trong chiến lược \"Chiến tranh đặc biệt\" ở miền Nam","Nhân dân thế giới lên án"],"b","(Kết quả đúng: Bị thiệt hại nặng nề ở cả hai miền Nam - Bắc cuối năm 1968)"],[420,"Nghị quyết số 03-NQ/TW tại Hội nghị Trung ương 5 khóa VIII (7/1998) được coi như:",["Tuyên ngôn văn hóa của Đảng trong thời kỳ thực hiện công nghiệp hóa, hiện đại hóa","Tuyên ngôn văn nghệ của Đảng trong thời kỳ thực hiện công nghiệp hóa, hiện đại hóa","Tuyên ngôn nghệ thuật của Đảng trong thời kỳ thực hiện công nghiệp hóa, hiện đại hóa","Tuyên ngôn văn hóa văn nghệ của Đảng trong thời kỳ toàn cầu hóa"],"a",""],[421,"Hội nghị Giơnevơ tháng 5/1954 đàm phán diễn ra trong bao nhiêu ngày?",["75 ngày","70 ngày","81 ngày","55 ngày"],"a",""],[422,"Chiến lược \"Chiến tranh cục bộ\" của đế quốc Mỹ là:",["Cuộc chiến tranh xâm lược kiểu mới, tiến hành bằng lực lượng quân đội Mỹ, quân đồng minh và quân đội Sài Gòn","Tiến hành bằng quân Mỹ và bọn tay sai phản động Sài Gòn","Tiến hành bằng quân đồng minh cùng trang thiết bị hiện đại của Mỹ","Tiến hành bằng lực lượng quân đội Mỹ"],"a",""],[423,"Chiến lược phát triển khoa học và công nghệ, giáo dục và đào tạo đã được đề ra từ năm 1996 nhằm:",["Thúc đẩy mạnh mẽ sự nghiệp công nghiệp hóa, hiện đại hóa đất nước.","Thúc đẩy mạnh mẽ sự nghiệp công nghiệp hóa đất nước.","Thúc đẩy mạnh mẽ sự nghiệp phát triển kinh tế đất nước","Thúc đẩy mạnh mẽ sự nghiệp giáo dục"],"a",""],[424,"Với chính sách cai trị của thực dân Pháp, sau Cách mạng tháng Tám năm 1945, nước ta có khoảng bao nhiêu % dân số mù chữ?",["Hơn 60% dân số không biết chữ","Hơn 70% dân số không biết chữ","Hơn 80% dân số không biết chữ","Hơn 90% dân số không biết chữ"],"d",""],[425,"Đại hội lần thứ V của Đảng đã khẳng định: \"Trong khi không một phút lợi lòng nhiệm vụ cũng cố quốc phòng, bảo vệ Tổ quốc, Đảng ta và nhân dẫn phải đặt lên hàng đầu...\". Từ nào còn thiếu trong nhận định trên?",["Nhiệm vụ xây dựng chủ nghĩa xã hội","Mục tiêu của cách mạng Việt Nam","Vấn đề cơ bản của cách mạng Việt Nam","Vấn đề cơ bản khi xây dựng chủ nghĩa xã hội"],"a",""],[426,"Tại Hội nghị thành lập Đảng, điều nào được thống nhất về vai trò của Đảng trong cách mạng Việt Nam?",["Đảng chi cần lãnh đạo phong trào công nhân","Đảng là đội tiên phong của giai cấp công nhân và toàn thê dân tộc","Đảng không cần thiết phải có tổ chức chính thức","Đảng sẽ tự động phát triến mà không cần sự lãnh đạo"],"b",""],[427,"So với Cương lĩnh chính trị đầu tiên, Luận cương chính trị tháng 10/1930 đã có điểm gì khác biệt trong giải quyết các nhiệm vụ phản để quốc và phản phong kiến?",["Không đặt nhiệm vụ phản để quốc lên hàng đầu","Đặt nhiệm vụ phản đế quốc lên hàng đầu","Không xác định được nhiệm vụ nào cần được đặt lên hàng đầu","Đặt nhiệm vụ phản đế quốc ngang bằng nhiệm vụ phản phong kiến"],"d",""],[428,"Chủ đề của Đại hội Đảng Cộng sản Việt Nam lần thứ XIII năm 2021 là gì?",["Phát huy sức mạnh toàn dân tộc, tiếp tục đổi mới, đẩy mạnh công nghiệp hóa, hiện đại hòa, xây dựng và bảo vệ Tổ quốc Việt Nam Xã hội chủ nghĩa","Tiếp tục sự nghiệp đổi mới, đẩy mạnh công nghiệp hóa, hiện đại hóa vì mục tiêu dân giàu, nước mạnh, xã hội công bằng, văn minh, vững bước đi lên chủ nghĩa xã hội","Tăng cường xây dựng, chỉnh đốn Đảng và hệ thống chính trị trong sạch, vững mạnh; khơi dậy khát vọng phát triển đất nước, phát huy ý chí, sức mạnh đại đoàn kết toàn dân tôc kết hợp với sức mạnh thời đại","Tiếp tục đấy mạnh toàn diện, đông bộ công cuộc đổi mới; xây dựng và bảo vệ vững chắc Tổ quốc, giữ vững môi trường hòa bình, ốn đinh, phấn đầu đến giữa thế kỷ XXI, nước ta trở thành nước phát triển, theo định hướng xã hội chủ nghĩa"],"c","(Kiểu hỏi khác: Chủ đê của Đại hội đại biểu toàn quốc lần thứ XIII của Đảng Cộng sản Việt Nam là? )"],[429,"Phương án nào đúng nhất nói khái quát về thành tựu của đất nước qua 35 năm đổi mới dưới sự lãnh đạo của Đảng?",["Đất nước ta chưa khi nào có được cơ đồ, tiềm lực, vị thế và uy tín quốc tế như ngày nay nếu không có Đảng lãnh đạo","Đất nước ta chưa bao giờ có được cơ đồ, tiềm lực, vị thế và uy tín quốc tế như ngày nay","Đất nước ta chưa bao giờ có được cơ đồ, tiềm lực, vị thế và uy tín như ngày nay","Đất nước ta chưa bao giờ có được cơ đồ, tiềm lực, vị thế và uy tín quốc tế như ngày nay nếu không có Đàng quản lý, Nhà nước lãnh đạo"],"b",""],[430,"Ngày 2/9/1945, quân Pháp trắng trợn gây hấn cho nổ súng vào những người tham gia míttinh mừng ngày độc lập ở đâu?",["Sài Gòn - Chợ Lớn","Hà Nội.","Khu căn cứ cách mạng.","An toàn khu"],"a",""],[431,"Từ năm 1930 đến nay, Đảng Cộng sản Việt Nam đã đề ra mấy Cương lĩnh chính trị?",["3","4","5","6"],"c",""],[432,"Đâu là một trong những phương pháp cụ thể khi nghiên cứu, học tập Lịch sử Đảng Cộng sản Việt Nam?",["Khái quát hóa, trừu tượng hóa","Liên kết, phán đoán","Lịch sử, logic","Nghiên cứu tài liệu"],"c",""],[433,"Đại hội lần thứ V của Đảng đã xác định nội dung, bước đi, cách làm thực hiện công nghiệp hoá xã hội chủ nghĩa trong chặng đường đầu tiên là gì?",["Tập trung sức phát triển mạnh nông nghiệp, coi nông nghiệp là mặt trận hàng đầu","Đảm bảo xây dụng Đàng trong sạch vũng mạnh, tiến lên chủ nghĩa xã hội","Đẩy mạnh cách mạng tư tưởng và văn hoa, xây dụng và phát triển nền văn hoá mới","Tăng cường xây dụng Nhà nước xã hội chủ nghĩa, phát huy vai trò của các đoàn thể"],"a",""],[434,"Năm 1936 khi thành lập Chính phủ Mặt trận nhân dân Pháp thì Chính phủ này đã có hành động gì ảnh hường đến các thuộc địa?",["Tăng cường đàn áp, vơ vét thuộc địa","Sử dụng bộ máy cai trị trực tiếp người Pháp ở thuộc địa thay thế dân bản xứ","Ban bố một số quyền tự do, dân chủ được áp dụng ở thuộc địa","Tuyên bố quyền tự quyết, độc lập của các thuộc địa"],"c",""],[435,"Theo lời kêu gọi của Chủ tịch Hồ Chí Minh, quân dân miền Bắc đã dấy lên các phong trào: Ba sẵn sàng là của ...; Tay cày, tay súng là của ... và nhằm thẳng quân thù mà bắn là ở phong trào trong ... , cụm từ còn thiếu trong dấu \"... \" là?",["Phong trào thanh niên/Phong trào nông dân/Chiến đấu","Phong trào phụ nữ/Phong trào công nhân, nông dân/Chiến đấu","Phong trào công nhân, nong dân/Phong trao thanh nien/Chien đấu","Phong trào chiến đấu/Phong trào nông dân/Khẩu hiệu"],"a",""],[436,"Hội nghị nào của Đàng đã quyết định mở cuộc Tổng tấn công và nổi dậy Mậu Thân 1968?",["Hội nghị Trung ưong 13 - Khóa III của Đảng (1-1967)","Hội nghị Bộ Chính trị (5-1967)","Hội nghị Bộ Chính trị (10-1967)","Hội nghị lần thứ 14 BCH Trung ưong Đảng - khóa III (12-1967)"],"d",""],[437,"Chức năng giáo dục của Khoa học Lịch sử Đảng Cộng sản Việt Nam là gì?",["Giáo dục lòng yêu nước, yêu nhân dân và con người","Giáo dục lý tưởng cách mạng, với mục tiêu độc lập dân tộc gắn liền chủ nghĩa xã hội","Giáo dục lý tưởng người cách mạng","Giáo dục thanh niên học sinh, những người yêu nước"],"b",""],[438,"Ý nghĩa tên \"Đội Việt Nam tuyên truyền giải phóng quân\" là gì?",["Chính trị trọng hơn quân sự","Tuyên truyền trọng hơn giài phóng","Tuyên truyền cũng chính là cách giải phóng","Vì thiếu quân nên cán bộ tuyên truyền kiêm giài phóng quân"],"a",""]];
